function invoicePreview(list,editable=false){let late=list[0]?.latePolicy||LateTax.policy(db,billingKind);return '<div class="table-wrap"><table class="invoice-issue-table"><thead><tr><th>โกดัง / รอบเรียกเก็บ</th><th>กำหนดชำระ</th><th>VAT</th><th>หัก ณ ที่จ่าย</th><th class="num">ค่าปรับ</th><th class="num">ยอดรวม</th><th class="num">หักภาษี</th><th class="num">สุทธิให้ชำระ</th></tr></thead><tbody>'+list.map(i=>{let p=i.taxPlan;return '<tr><td><b>'+E(i.roomName)+'</b><small>'+E(i.tenantName)+'</small><small>'+date(i.serviceFrom)+' – '+date(i.serviceTo)+'</small></td><td>'+date(i.due)+'</td><td>'+(editable&&i.category==='rent'?'<select aria-label="VAT '+E(i.roomName)+'" data-invoice-tax="'+i.contractId+'" data-tax-key="rentVatMode"><option value="none" '+(p?.rentVatMode==='none'?'selected':'')+'>ไม่ VAT</option><option value="included" '+(p?.rentVatMode==='included'?'selected':'')+'>รวม VAT</option></select>':M(p?.vat||0))+'</td><td>'+(editable?'<label class="tax-rate-inline"><input aria-label="หัก ณ ที่จ่าย '+E(i.roomName)+'" type="number" min="0" max="100" step="any" value="'+E(p?.withholding.rate||0)+'" data-invoice-tax="'+i.contractId+'" data-tax-key="whtRate">%</label>':E(p?.withholding.rate||0)+'%')+'</td><td class="num">'+M(i.lateAssessments?.reduce((n,x)=>n+x.amount,0)||0)+'</td><td class="num">'+M(i.total)+'</td><td class="num">'+'<span data-preview-withheld>'+M(p?.withholding.amount||0)+'</span></td><td class="num"><strong data-preview-net>'+M(p?.netDue??i.total)+'</strong></td></tr>';}).join('')+'</tbody></table></div><div class="issue-terms"><b>ค่าปรับหลังครบกำหนด</b><span>'+E(late.enabled?'ผ่อนผัน '+late.grace+' วัน · ตั้งแต่วันที่ '+(Number(late.grace)+1)+(late.mode==='daily'?' วันละ '+M(late.rate)+' บาท':' อัตรา '+late.rate+'% ต่อปี')+' · ไม่คิดย้อนหลังช่วงผ่อนผัน':'ไม่เรียกค่าปรับ')+'</span><small>ดึงเงื่อนไขภาษีจากข้อมูลผู้เช่าอัตโนมัติ · หัก ณ ที่จ่ายในใบแจ้งเป็นยอดคาดไว้ตามเงื่อนไข ผู้จ่ายหักจริงเมื่อชำระเงินและส่งหนังสือรับรอง</small></div>';}
function payments(scoped,title){let list=(scoped||db.rp3.invoices.filter(i=>!i.category)).filter(i=>(allPeriods||i.period===period)&&(filter==='all'||filter==='unpaid'&&i.state==='issued'&&RP.balance(db,i)>0||filter==='paid'&&status(i)==='ชำระแล้ว'||filter==='overdue'&&status(i)==='เกินกำหนด'));if(search)list=list.filter(i=>(i.number+' '+i.roomName+' '+i.tenantName).toLowerCase().includes(search.toLowerCase()));let controls='<div class="collection-filters"><div class="status-segments">'+[['all','ทั้งหมด'],['unpaid','ค้างชำระ'],['paid','ชำระแล้ว'],['overdue','เกินกำหนด']].map(([key,label])=>'<button data-filter="'+key+'" class="'+(filter===key?'on':'')+'">'+label+'</button>').join('')+'</div><div class="collection-search"><input id="search" class="search" type="search" aria-label="ค้นหาใบแจ้งค่าใช้จ่าย" placeholder="ค้นหาห้อง ผู้เช่า เลขที่บิล" value="'+E(search)+'"><label class="all-months"><input id="all-periods" type="checkbox" '+(allPeriods?'checked':'')+'>ทุกเดือน</label>'+btn('ส่งออก','csv','small')+'</div></div>';return panel('ใบแจ้ง'+(title||'ค่าใช้จ่ายเดิม')+' · '+(allPeriods?'ทุกเดือน':month(period)),controls+invoiceTable(list));}
function properties(){let rooms=db.rooms.filter(r=>showArchivedRooms||!r.archived),r=rooms.find(r=>r.id===selectedRoom)||rooms[0];if(!r)return '<div class="empty">ไม่มีโกดังที่กำลังใช้งาน '+btn('+ เพิ่มโกดัง','add-room','primary')+(db.rooms.some(x=>x.archived)?'<p>มีโกดังที่ปิดใช้งานอยู่ ข้อมูลเดิมยังเก็บไว้ '+btn('ดูโกดังที่ปิดใช้งาน','toggle-archived-rooms','small')+'</p>':'')+'</div>';selectedRoom=r.id;let cs=db.contracts.filter(c=>c.roomId===r.id&&!c.archived).sort((a,b)=>b.startDate.localeCompare(a.startDate)),c=cs.find(c=>c.startDate<=today&&c.endDate>=today)||cs[0],t=c&&db.tenants.find(t=>t.id===c.tenantId);let keyValue=(key,v)=>'<div><span class="key">'+key+'</span><div class="value">'+E(v||'—')+'</div></div>';return '<div class="property-layout"><div class="room-list">'+rooms.map(room=>'<button data-room="'+room.id+'" class="'+(room.id===r.id?'on':'')+'"><div class="label"><strong>'+E(room.name)+'</strong>'+tag(room.archived?'ปิดใช้งาน':db.contracts.some(c=>c.roomId===room.id&&!c.archived&&c.startDate<=today&&c.endDate>=today)?'มีผู้เช่า':db.contracts.some(c=>c.roomId===room.id&&!c.archived&&c.startDate>today)?'รอเริ่มสัญญา':'ว่าง')+'</div><small>'+Number(room.size||0)+' ตร.ม. · ค่าเช่า '+M(room.rent)+'</small></button>').join('')+'</div><div><div class="property-top"><div><h2>'+E(r.name)+'</h2><span class="muted">'+E(r.desc||'ข้อมูลโกดังและประวัติผู้เช่า')+'</span></div><div class="tools">'+btn('แก้ไขโกดัง','edit-room','','data-id="'+r.id+'"')+(r.archived?tag('ปิดใช้งาน'):btn('ปิดใช้งาน','archive-room','danger small','data-id="'+r.id+'"'))+'</div></div>'+panel('ข้อมูลโกดัง','<div class="panel-body"><div class="details-grid">'+keyValue('พื้นที่',Number(r.size||0)+' ตร.ม.')+keyValue('ค่าเช่าพื้นฐาน',M(r.rent)+' บาท / เดือน')+keyValue('รายละเอียด',r.facilities)+keyValue('ตำแหน่ง',r.floor)+'</div></div>')+panel('ผู้เช่าและสัญญา','<div class="panel-body">'+(t?'<div class="details-grid">'+keyValue('ผู้เช่า',tenant(t.id))+keyValue('เบอร์ติดต่อ',t.phone)+keyValue('อีเมล',t.email)+keyValue('ที่อยู่',t.address)+keyValue('หัก ณ ที่จ่าย (ค่าเริ่มต้นบิลใหม่)','ค่าเช่า '+InvoiceTax.tenantTerms(t).whtRate+'% · น้ำ '+InvoiceTax.tenantTerms(t).waterWhtRate+'% · ไฟ '+InvoiceTax.tenantTerms(t).electricWhtRate+'%')+keyValue('VAT ค่าเช่า (บิลใหม่)',({'none':'ไม่ VAT / ยกเว้น VAT','included':'รวม VAT ในยอดแล้ว'})[InvoiceTax.tenantTerms(t).rentVatMode]||'ตามการตั้งค่าโครงการ')+keyValue('เลขที่สัญญา',c.number||c.id)+keyValue('วันทำสัญญา',date(c.signedDate||c.startDate))+keyValue('ช่วงสัญญา',date(c.startDate)+' – '+date(c.endDate))+keyValue('ค่าเช่าตามสัญญา',M(c.rent)+' บาท / เดือน')+keyValue('เงินประกัน',M(c.deposit)+' บาท')+keyValue('รอบค่าเช่า','เริ่มวันที่ '+Number(SplitBilling.rentStart(c).slice(8))+' ของแต่ละเดือน ถึงวันก่อนรอบถัดไป')+keyValue('กำหนดชำระค่าเช่า',c.billingSchedule==='anniversary'?'วันเริ่มรอบสัญญา':'วันที่ '+(c.dueDay||1)+' ของเดือน')+keyValue('ค่าน้ำ / ค่าไฟ','แยกรอบบิลจริง · ครบกำหนด '+(c.utilityDueDays??7)+' วันหลังสิ้นรอบ')+keyValue('วัตถุประสงค์การเช่า',c.permittedUse||c.purpose)+keyValue('ผู้ประสานงาน',c.tenantContact||t.contactPerson)+keyValue('มิเตอร์น้ำ / ไฟ',((c.waterMeterNo||'—')+' / '+(c.electricMeterNo||'—')))+'</div><div class="tools" style="margin-top:20px">'+btn('แก้ไขผู้เช่า','edit-tenant','','data-id="'+t.id+'"')+btn('แก้ไขสัญญา','edit-contract','','data-id="'+c.id+'"')+btn('แนบรูปส่งมอบ'+(c.handoverPhotos?.length?' ('+c.handoverPhotos.length+')':''),'lease-photos','','data-id="'+c.id+'"')+btn('เอกสารแนบท้าย','lease-documents','','data-id="'+c.id+'"')+btn('สัญญาฉบับเต็ม','full-lease','','data-id="'+c.id+'"')+btn('ยุติสัญญา','end-contract','danger small','data-id="'+c.id+'"')+'</div>':'<div class="empty">ยังไม่มีสัญญาที่กำลังใช้งาน · สัญญาเดิมดูได้จากประวัติด้านล่าง<br>'+(!r.archived?btn('เพิ่มผู้เช่าและสัญญา','new-contract','primary','data-id="'+r.id+'"'):'')+'</div>')+'</div>')+(c?depositPanel(c):'')+panel('ประวัติสัญญา','<div class="table-wrap"><table><thead><tr><th>ผู้เช่า</th><th>ระยะเวลา</th><th>สถานะ</th><th></th></tr></thead><tbody>'+db.contracts.filter(x=>x.roomId===r.id).map(x=>'<tr><td>'+E(tenant(x.tenantId))+'</td><td>'+date(x.startDate)+' – '+date(x.endDate)+'</td><td>'+tag(x.archived?'ยุติแล้ว':x.startDate>today?'รอเริ่ม':x.endDate<today?'หมดอายุ':'ใช้งาน')+'</td><td>'+btn('สัญญาฉบับเต็ม','full-lease','small','data-id="'+x.id+'"')+btn('เงินประกัน / ประวัติ','contract-deposits','small','data-id="'+x.id+'"')+'</td></tr>').join('')+'</tbody></table></div>')+panel('ประวัติใบแจ้งค่าใช้จ่ายของหลังนี้',invoiceTable(db.rp3.invoices.filter(i=>i.roomId===r.id),true))+'</div></div>';}
function depositPanel(c){let rows=(db.rp3.deposits||[]).filter(x=>x.contractId===c.id),held=DepositLedger.held(db,c.id),received=rows.filter(x=>x.kind==='receive').reduce((n,x)=>n+x.amount,0);return panel('เงินประกันและค่าเช่าล่วงหน้า · '+E(c.number),'<div class="panel-body"><div class="details-grid"><div><span class="key">เงินประกันตามสัญญา</span><b>'+M(c.deposit)+' บาท</b></div><div><span class="key">รับเงินประกันสะสม</span><b>'+M(received)+' บาท</b></div><div><span class="key">เงินประกันคงเหลือที่ถืออยู่</span><b>'+M(held)+' บาท</b></div><div><span class="key">ค่าเช่าล่วงหน้าตามสัญญา</span><b>'+M(c.advance)+' บาท</b><small>ชำระค่าเช่างวดแรก · อ้างอิงบิลและใบเสร็จงวดแรก ไม่เก็บซ้ำ</small></div></div><div class="tools" style="margin-top:15px">'+btn('ใบแจ้งเงินประกัน','deposit-notice','','data-id="'+c.id+'"')+btn('รับ / คืน / หักเงินประกัน','deposit-modal','','data-id="'+c.id+'"')+(!c.archived?btn('ใบแจ้งค่าเช่าล่วงหน้า / งวดแรก','first-rent-preview','','data-id="'+c.id+'"'):'')+'</div>'+'</div>'+(rows.length?'<div class="table-wrap"><table><thead><tr><th>วันที่ / เลขที่</th><th>รายการ</th><th>รายละเอียด</th><th class="num">บาท</th><th></th></tr></thead><tbody>'+rows.map(x=>'<tr><td>'+date(x.date)+'<small>'+E(x.number)+'</small></td><td>'+({receive:'รับเงินประกัน',refund:'คืนเงินประกัน',deduct:'หักเงินประกัน'}[x.kind])+'</td><td>'+E(x.note)+'</td><td class="num">'+M(x.amount)+'</td><td>'+btn('เอกสาร','deposit-document','small','data-id="'+x.id+'"')+(x.proof?btn('ดูสลิป','deposit-proof','small','data-id="'+x.id+'"'):btn('แนบสลิป','deposit-attach','small','data-id="'+x.id+'"'))+'</td></tr>').join('')+'</tbody></table></div>':'<div class="empty">ยังไม่มีการรับเงินจริง · ยอดในสัญญาไม่ถือว่ารับเงินแล้ว</div>'));}
function depositModal(id){let c=db.contracts.find(c=>c.id===id);if(!c)throw Error('ไม่พบสัญญา');if(!c.depositNotice&&DepositLedger.held(db,id)<=0){depositNoticeModal(id);return;}let canReceive=c.depositNotice&&DepositLedger.noticeRemaining(db,c.depositNotice)>0;modal('บันทึกเงินประกัน',dataForm('deposit-form','<label class="field">รายการ<select name="kind"><option value="receive" '+(!canReceive?'disabled':'selected')+'>รับเงินประกัน</option><option value="refund" '+(!canReceive?'selected':'')+'>คืนเงินประกัน</option><option value="deduct">หักเงินประกันตามข้อตกลง</option></select></label>'+field('จำนวนเงิน (บาท)','amount','','number','min="0.01" required')+field('วันที่ทำรายการ','date',today,'date','required max="'+today+'"')+field('ช่องทาง / เลขอ้างอิง','method','')+area('รายละเอียด / เหตุผล (จำเป็น)','note','')+'<label class="field wide">แนบสลิปรับ / คืนเงินประกัน · ไม่เกิน 5 MB<input type="file" data-file="proof" accept="image/png,image/jpeg,image/webp"></label><div id="proof-name" class="image-label wide"></div>')+'<p id="deposit-limit" class="muted"></p>',btn('ปิด','close')+btn('บันทึกเงินประกัน','deposit-save','primary','data-id="'+id+'"'));$('deposit-form').dataset.contractId=id;updateDepositLimit();}
function updateDepositLimit(){let f=$('deposit-form');if(!f)return;let c=db.contracts.find(c=>c.id===f.dataset.contractId),receive=f.elements.kind.value==='receive',max=receive?Math.max(0,Math.min(Number(c.deposit||0)-DepositLedger.held(db,c.id),c.depositNotice?DepositLedger.noticeRemaining(db,c.depositNotice):0)):DepositLedger.held(db,c.id);f.elements.amount.max=max;if(!f.elements.amount.value)f.elements.amount.value=max;$('deposit-limit').textContent=receive?'อ้างอิงใบแจ้ง '+(c.depositNotice?.number||'—')+' · ค้างรับ '+M(max)+' บาท · เงินประกันแยกจากค่าเช่า':'เงินประกันที่ถืออยู่ '+M(max)+' บาท';}
function depositNoticeHTML(n){let left=DepositLedger.noticeRemaining(db,n),t=n.tenant;return '<article class="billing-sheet">'+(demo?'<div class="demo-watermark">ข้อมูลตัวอย่าง</div>':'')+'<header class="billing-head"><div><h2>'+E(n.owner.billCompany||n.owner.name)+'</h2><p>'+E(n.owner.address||'')+'</p></div><h1>ใบแจ้งเงินประกัน</h1></header><p>เลขที่ '+E(n.number)+' · วันที่ '+date(n.date)+'</p><p>สัญญา '+E(n.contractNumber)+' · '+E(n.roomName)+'</p><p>ผู้เช่า '+E((t.prefix||'')+(t.fname||'')+' '+(t.lname||''))+'</p><table><tr><td>เงินประกันตามสัญญา</td><td class="num">'+M(n.agreed)+' บาท</td></tr><tr><td>เงินประกันที่ถืออยู่ ณ วันออกใบแจ้ง</td><td class="num">'+M(n.held)+' บาท</td></tr><tr><td>ยอดแจ้งเรียกเก็บเงินประกัน</td><td class="num">'+M(n.amount)+' บาท</td></tr></table><div class="bill-grand">คงเหลือตามใบแจ้ง '+M(left)+' บาท</div><p>ช่องทางชำระเงิน<br>'+E(n.owner.bank||'—').replace(/\n/g,'<br>')+'</p><p>เงินประกันความเสียหาย แยกจากค่าเช่าล่วงหน้าและค่าสาธารณูปโภค</p><p>เอกสารนี้เป็นใบแจ้งเรียกเก็บเงิน ไม่ใช่หลักฐานรับเงิน</p></article>';}
function depositNoticeModal(id){let c=db.contracts.find(c=>c.id===id);if(!c)throw Error('ไม่พบสัญญา');let existing=!!c.depositNotice,n=existing?c.depositNotice:null;if(!n){let copy=C(db);n=DepositLedger.issueNotice(copy,id,uid(),today);}let html=depositNoticeHTML(n);modal(existing?'ใบแจ้งเงินประกัน':'ตรวจใบแจ้งเงินประกัน','<div class="billing-preview">'+html+'</div>',btn('ปิด','close')+(existing?btn('พิมพ์ / บันทึก PDF','deposit-print')+(DepositLedger.noticeRemaining(db,n)>0&&!c.archived?btn('รับเงินตามใบแจ้ง','deposit-modal','primary','data-id="'+id+'"'):'')+(DepositLedger.noticeRemaining(db,n)===0&&Number(c.deposit)>DepositLedger.held(db,id)&&!c.archived?btn('ออกใบแจ้งยอดคงเหลือ','deposit-notice-issue','primary','data-id="'+id+'"'):''):btn('ออกใบแจ้งเงินประกัน','deposit-notice-issue','primary','data-id="'+id+'"')),true);modalData.depositHTML=html;}

function depositDocument(id){let x=db.rp3.deposits.find(x=>x.id===id),c=db.contracts.find(c=>c.id===x.contractId),o=x.owner,title={receive:'ใบรับเงินประกัน',refund:'หลักฐานคืนเงินประกัน',deduct:'หลักฐานหักเงินประกัน'}[x.kind];let html='<article class="billing-sheet">'+(demo?'<div class="demo-watermark">ข้อมูลตัวอย่าง · ไม่ใช่เอกสารรับเงินจริง</div>':'')+'<header class="billing-head"><div><h2>'+E(o.billCompany||o.name)+'</h2>'+E(o.address)+'<p>เลขประจำตัวผู้เสียภาษี '+E(o.billTaxId||o.idcard||'—')+'</p></div><h1>'+title+'</h1></header><p>เลขที่ '+E(x.number)+' · วันที่ '+date(x.date)+'</p><p>สัญญา '+E(c.number)+' · '+E(db.rooms.find(r=>r.id===x.roomId)?.name)+'</p><p>ผู้เช่า '+E((x.tenant.fname||'')+' '+(x.tenant.lname||''))+'</p><div class="bill-grand">จำนวนเงิน '+M(x.amount)+' บาท</div><p>'+E(x.note)+'</p><p>ช่องทาง / อ้างอิง '+E(x.method)+'</p><div class="sign"><span>ผู้จ่ายเงิน ................................</span><span>ผู้รับเงิน ................................</span></div><p>เอกสารเงินประกัน แยกจากใบเสร็จค่าเช่าและค่าสาธารณูปโภค</p></article>';modal(title,'<div class="billing-preview">'+html+'</div>',btn('ปิด','close')+btn('พิมพ์ / บันทึก PDF','deposit-print','primary','data-id="'+id+'"'),true);modalData.depositHTML=html;}

function categoryPage(){if(page==='rent')billingKind='rent';else if(billingKind==='rent')billingKind='water';let nav='<div class="workspace-segments">'+(page==='utilities'?[['water','ค่าน้ำประปา'],['electric','ค่าไฟฟ้า']].map(([k,t])=>'<button data-utility-kind="'+k+'" class="'+(billingKind===k?'on':'')+'">'+t+'</button>').join(''):'')+'<button data-category-view="list" class="'+(categoryMode!=='accounting'?'on':'')+'">รายการ'+(page==='rent'?'ค่าเช่า':chargeLabels[billingKind])+'</button><button data-category-view="accounting" class="'+(categoryMode==='accounting'?'on':'')+'">สรุปส่งบัญชี</button></div>',bar='<div class="billing-toolbar">'+nav+(categoryMode==='list'?btn('+ ออกใบแจ้ง'+chargeLabels[billingKind],'category-issue','primary'):'')+'</div>';if(categoryMode==='accounting')return bar+taxPage();if(categoryMode==='issue')return bar+'<div class="tools">'+btn('← กลับรายการ','category-list')+'</div>'+billing().replace(/<div class="tabs">[\s\S]*?<\/div>/,'');let list=db.rp3.invoices.filter(i=>i.category===billingKind&&(allPeriods||i.period===period));return bar+payments(list,chargeLabels[billingKind]);}
function financeSettings(){let o=db.owner;return panel('ค่าปรับล่าช้าและข้อมูลภาษี','<div class="panel-body"><div class="notice">เงื่อนไขค่าปรับ: ผ่อนผัน 5 วันหลังครบกำหนด ตั้งแต่วันที่ 6 วันละ 200 บาท ไม่ย้อนหลัง 5 วันแรก · บิลใหม่เก็บกติกาไว้กับบิล บิลเก่าก่อนวันที่เริ่มใช้ไม่ถูกคิดย้อนหลัง</div>'+dataForm('finance-settings','<label class="field">ผู้รับเงิน / ผู้ให้เช่า<select name="taxEntityType">'+[['','ยังไม่ระบุ'],['person','บุคคลธรรมดา'],['company','บริษัท / นิติบุคคล']].map(([v,t])=>'<option value="'+v+'" '+(o.taxEntityType===v?'selected':'')+'>'+t+'</option>').join('')+'</select></label><label class="field">การจดทะเบียน VAT<select name="vatRegistration">'+[['unknown','ยังไม่ยืนยัน'],['unregistered','ไม่ได้จด VAT'],['registered','จดทะเบียน VAT แล้ว']].map(([v,t])=>'<option value="'+v+'" '+((o.vatRegistration||'unknown')===v?'selected':'')+'>'+t+'</option>').join('')+'</select></label>'+['rent','water','electric'].map(k=>{let r=LateTax.policy(db,k);return '<fieldset class="wide"><legend>'+chargeLabels[k]+'</legend><div class="fields"><label class="field">การเรียกค่าปรับ<select name="'+k+'_enabled"><option value="off">ปิด</option><option value="on" '+(r.enabled?'selected':'')+'>เปิดตามข้อตกลง</option></select></label><label class="field">วิธีคิด<select name="'+k+'_mode"><option value="daily">บาทต่อวัน</option><option value="annual" '+(r.mode==='annual'?'selected':'')+'>เปอร์เซ็นต์ต่อปีจากยอดค้างจริง (365 วัน)</option></select></label>'+field('อัตรา (บาท/วัน หรือ %/ปี)',k+'_rate',r.rate,'number','min="0" required')+field('ผ่อนผันกี่วันหลังครบกำหนด',k+'_grace',r.grace,'number','min="0" step="1" required')+field('เพดานต่อบิล (0 = ไม่กำหนด)',k+'_cap',r.cap,'number','min="0" required')+field('ใช้กับบิลที่ครบกำหนดตั้งแต่ (ว่าง = ไม่จำกัดวัน)',k+'_from',r.from,'date')+'</div></fieldset>';}).join(''))+'<div class="tools">'+btn('บันทึกค่าปรับและภาษี','finance-settings-save','primary')+'</div><p class="muted">ค่าเช่าอสังหาริมทรัพย์โดยทั่วไปยกเว้น VAT · VAT บนต้นทุนค่าน้ำไฟไม่ใช่สิทธิออกใบกำกับภาษีของผู้ให้เช่า · ตรวจการจัดประเภทกับบัญชีก่อนนำยื่น</p></div>');}
function taxPage(){let rows=LateTax.report(db,period).filter(x=>page==='rent'?x.i.category==='rent':['water','electric'].includes(x.i.category)),sum=k=>RP.money(rows.reduce((n,x)=>n+x[k],0)),pending=rows.filter(x=>x.withheld&&x.r.withholding.status!=='received'),form=db.owner.taxEntityType==='company'?'ภ.ง.ด.53':db.owner.taxEntityType==='person'?'ภ.ง.ด.3':'ยังไม่ระบุประเภทผู้ให้เช่า';return '<div class="metrics">'+metric('ยอดชำระหนี้',M(sum('gross')),'รวมเงินรับจริงและภาษีถูกหัก')+metric('รับเงินจริง',M(sum('cash')),'ยอดสุทธิรับเข้าบัญชี / เงินสด')+metric('ภาษีถูกหัก ณ ที่จ่าย',M(sum('withheld')),'รอหนังสือรับรอง '+pending.length+' รายการ')+'</div><div class="notice">ผู้ให้เช่า: '+E(db.owner.taxEntityType==='company'?'นิติบุคคล':db.owner.taxEntityType==='person'?'บุคคลธรรมดา':'ยังไม่ระบุ')+' · แบบที่ผู้จ่ายใช้ส่งภาษีถูกหัก: '+form+'<br>การจด VAT: '+E({registered:'จดแล้ว',unregistered:'ไม่ได้จด',unknown:'ยังไม่ยืนยัน'}[db.owner.vatRegistration||'unknown'])+' · รายงานนี้เป็นชุดตรวจสำหรับบัญชี ไม่ใช่แบบยื่นภาษีหรือใบกำกับภาษี '+btn('ตั้งค่าข้อมูลภาษี','finance-settings','link')+'</div>'+panel('รับชำระและหนังสือรับรอง · '+month(period),'<div class="table-wrap"><table><thead><tr><th>วันที่ / ผู้เช่า</th><th>เอกสาร / ประเภท</th><th class="num">ก่อน VAT ที่แสดง</th><th class="num">VAT ที่แสดง*</th><th class="num">ถูกหัก</th><th class="num">รับจริง</th><th>หนังสือรับรอง</th></tr></thead><tbody>'+rows.map(x=>'<tr><td>'+date(x.r.date)+'<small>'+E(x.i.tenantName)+'</small></td><td>'+E(x.r.number)+'<small>'+E(chargeLabels[x.i.category]||'บิลรวมเดิม')+'</small></td><td class="num">'+M(x.base)+'</td><td class="num">'+M(x.vat)+'</td><td class="num">'+M(x.withheld)+'</td><td class="num">'+M(x.cash)+'</td><td>'+(x.withheld?(x.r.withholding.status==='received'?tag('ได้รับแล้ว')+'<small>'+E(x.r.withholding.certificateNumber)+'</small>':tag('รอเอกสาร'))+btn('บันทึกเลขรับรอง','wht-certificate','link','data-id="'+x.r.id+'"'):'—')+'</td></tr>').join('')+'</tbody></table></div><div class="panel-body"><p class="muted">* แสดงตามส่วนประกอบเอกสารที่ออกไว้ ไม่สรุปเป็นภาษีขายสำหรับ ภ.พ.30 อัตโนมัติ โดยเฉพาะต้นทุนค่าน้ำไฟและกิจการผสมยกเว้น VAT · เงินประกันคงเหลือแยกอยู่ในห้องและผู้เช่า</p><div class="tools">'+btn('ส่งออกรายงานให้บัญชี (CSV)','tax-export','primary')+'</div><p><a href="https://www.rd.go.th/35602.html" target="_blank" rel="noopener">กรมสรรพากร: ค่าเช่าอาคาร / VAT / หัก ณ ที่จ่าย</a> · <a href="https://interweb1.rd.go.th/publish/seminar/training/RD06.pdf" target="_blank" rel="noopener">ตัวอย่างค่าน้ำ–ไฟที่แยกเก็บ</a></p></div>');}
function invoiceTaxModal(id){let i=db.rp3.invoices.find(i=>i.id===id);if(!i||i.state!=='issued')throw Error('ไม่พบใบแจ้งที่แก้ไขได้');if(db.rp3.receipts.some(r=>r.invoiceId===id&&!r.voided))throw Error('บิลนี้รับชำระแล้ว ต้องคงเงื่อนไขภาษีเดิม');let p=i.taxPlan||InvoiceTax.plan(db,i);modal('ปรับภาษีในใบแจ้ง',dataForm('invoice-tax-form','<div class="notice wide">'+E(i.number)+' · '+E(i.tenantName)+'<br>ปรับใบแจ้งและตรวจยอดสุทธิก่อนส่งให้ผู้เช่า รับชำระจะใช้เงื่อนไขนี้</div>'+(i.category==='rent'?'<label class="field">VAT ของค่าเช่า<select name="rentVatMode"><option value="none" '+(p.rentVatMode==='none'?'selected':'')+'>ไม่ VAT / ยกเว้น VAT</option><option value="included" '+(p.rentVatMode==='included'?'selected':'')+'>รวม VAT ในยอดแล้ว (กรณีที่เกี่ยวข้อง)</option></select></label>':'<input type="hidden" name="rentVatMode" value="none">')+field('อัตราหัก ณ ที่จ่ายที่แจ้งผู้เช่า (%)','whtRate',p.withholding.rate,'number','min="0" max="100" required')+area('เหตุผลปรับใบแจ้ง (จำเป็น)','reason','เพิ่มเงื่อนไขภาษีและยอดสุทธิในใบแจ้ง')),btn('ปิด','close')+btn('บันทึกใบแจ้งปรับปรุง','invoice-tax-save','primary','data-id="'+id+'"'));}
function invoiceTaxNote(i){let p=i.taxPlan;if(!p)return '<div class="notice warn">บิลเดิมยังไม่มีเงื่อนไขหัก ณ ที่จ่ายในใบแจ้ง '+(i.state==='issued'&&!db.rp3.receipts.some(r=>r.invoiceId===i.id&&!r.voided)?btn('ปรับใบแจ้งก่อนรับชำระ','invoice-tax-edit','link','data-id="'+i.id+'"'):'ใช้ข้อมูลเดิมที่บันทึกไว้')+'</div>';return '<div class="notice"><div class="tax-summary-line"><span>ยอดรวมก่อนหัก</span><b>'+M(i.total)+' บาท</b></div><div class="tax-summary-line"><span>หัก ณ ที่จ่ายตามใบแจ้ง '+p.withholding.rate+'%</span><b>− '+M(p.withholding.amount)+' บาท</b></div><div class="tax-summary-line"><strong>ยอดสุทธิให้ชำระ</strong><strong>'+M(p.netDue)+' บาท</strong></div></div>';}
function withholdingFields(i,remaining){let amounts=InvoiceTax.payment(db,i,remaining);return amounts.rate>0?field('เลขหนังสือรับรองหัก ณ ที่จ่าย (เพิ่มภายหลังได้)','whtCertificate',''):'';}
function updateWithholding(){let f=$('receive-form');if(!f)return;let i=db.rp3.invoices.find(i=>i.id===f.dataset.invoiceId);if(!i)return;let saveButton=document.querySelector('[data-action="save-receipt"]');try{let allocations=Object.fromEntries(RP.chargeKeys.map(k=>[k,Number(f.elements['paid_'+k]?.value||0)])),a=InvoiceTax.payment(db,i,allocations);if(!(a.gross>0))throw Error('กรอกยอดชำระมากกว่า 0');if($('receive-total'))$('receive-total').textContent='฿'+M(a.cash);if($('receive-breakdown'))$('receive-breakdown').textContent='ยอดชำระหนี้ '+M(a.gross)+' บาท · หัก ณ ที่จ่าย '+M(a.amount)+' บาท'+(a.rate?' ('+a.rate+'%)':'');if(saveButton)saveButton.disabled=false;}catch(error){if($('receive-total'))$('receive-total').textContent='—';if($('receive-breakdown'))$('receive-breakdown').textContent=error.message;if(saveButton)saveButton.disabled=true;}}

function taxExport(){let data=[['วันที่','เลขใบเสร็จ','เลขบิล','ผู้เช่า','เลขผู้เสียภาษีผู้จ่าย','สาขาผู้จ่าย','ประเภท','ค่าปรับที่ชำระ','ยอดชำระหนี้','ฐานก่อน VAT ที่แสดง','VAT ที่แสดง-รอตรวจ','ฐานหัก ณ ที่จ่าย','อัตราหัก','ภาษีถูกหัก','รับเงินจริง','เลขหนังสือรับรอง','สถานะหนังสือรับรอง'],...LateTax.report(db,period).map(x=>[x.r.date,x.r.number,x.i.number,x.i.tenantName,x.r.document?.tenant?.idcard||'',x.r.document?.tenant?.branch||'',chargeLabels[x.i.category]||'บิลรวมเดิม',x.i.lateAssessments?.length?x.r.allocations?.other||0:0,x.gross,x.base??'รอตรวจ',x.vat??'รอตรวจ',x.r.withholding?.base||0,x.r.withholding?.rate||0,x.withheld,x.cash,x.r.withholding?.certificateNumber||'',x.r.withholding?.status||'none'])],text='\ufeff'+data.map(row=>row.map(v=>'"'+String(v).replace(/^[\s]*[=+@-]/,"'$&").replaceAll('"','""')+'"').join(',')).join('\r\n');let a=document.createElement('a'),url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='RentPro-accounting-'+period+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}

function accessTime(value){if(!value)return 'ยังไม่มีประวัติ';let date=new Date(value);if(Number.isNaN(date.getTime()))return '—';return date.toLocaleString('th-TH',{timeZone:'Asia/Bangkok',dateStyle:'medium',timeStyle:'short'});}
function usersPanel(){if(!demo&&!isRentAdmin)return '<div class="notice error">เฉพาะผู้ดูแลระบบเท่านั้น</div>';let directory=usersDirectory,rows=directory?.users||[],clock=new Date(directory?.server_time||now()).getTime(),recent=rows.filter(u=>u.last_seen_at&&clock-new Date(u.last_seen_at).getTime()>=0&&clock-new Date(u.last_seen_at).getTime()<=5*60000).length;
return (demo?'<div class="notice">ตัวอย่างหน้าผู้ดูแล · อีเมลและเวลาในหน้านี้เป็นข้อมูลสมมติ</div>':'')+'<div class="metrics">'+metric('ผู้ใช้งาน RentPro ทั้งหมด',directory?.total??'—','แสดงเฉพาะบัญชีที่เกี่ยวข้องกับ RentPro','properties')+metric('ใช้งานใน 5 นาทีล่าสุด',directory?recent:'—','อ้างอิงเวลาเปิดใช้งานล่าสุด','clock')+metric('ยืนยันอีเมลแล้ว',directory?rows.filter(u=>u.email_confirmed_at).length:'—','จากรายชื่อที่แสดง','payments')+'</div>'+panel('ผู้ใช้งาน RentPro',usersLoading?'<div class="loading" role="status">กำลังโหลดรายชื่อผู้ใช้งาน…</div>':usersError?'<div class="panel-body"><div class="notice error" role="alert">'+E(usersError)+'</div></div>':!directory?'<div class="empty">กดโหลดรายชื่อเพื่อดูผู้ใช้งาน</div>':'<div class="table-wrap"><table><thead><tr><th>บัญชีผู้ใช้งาน</th><th>สิทธิ์</th><th>สถานะยืนยัน</th><th>วันสมัคร</th><th>เข้าใช้งานล่าสุด</th><th>บันทึกข้อมูลล่าสุด</th></tr></thead><tbody>'+rows.map(u=>'<tr><td><b>'+E(u.email||'ไม่ระบุอีเมล')+'</b></td><td>'+E(u.is_admin?'ผู้ดูแล':'ผู้ใช้งาน')+'</td><td>'+E(u.email_confirmed_at?'ยืนยันแล้ว':'รอยืนยัน')+'</td><td>'+E(accessTime(u.created_at))+'</td><td>'+E(accessTime(u.last_seen_at))+'</td><td>'+E(accessTime(u.last_data_update))+'</td></tr>').join('')+'</tbody></table></div><div class="panel-body"><p class="muted">แสดง '+rows.length+' จาก '+directory.total+' บัญชี · อัปเดตเมื่อ '+E(accessTime(directory.server_time))+'<br>เวลาเข้าใช้งานล่าสุดเริ่มเก็บตั้งแต่เพิ่มฟังก์ชันนี้ · ข้อมูลเดิมดูได้จากเวลาบันทึกข้อมูลล่าสุด<br>เวลาทั้งหมดแสดงตามประเทศไทย · กดรีเฟรชเพื่อดูข้อมูลล่าสุด</p></div>',btn(directory?'รีเฟรชรายชื่อ':'โหลดรายชื่อ','refresh-users','small',usersLoading?'disabled':''));}
async function loadUsers(){if(usersLoading||!demo&&(!currentUser||!isRentAdmin))return;let ownerId=currentUser?.id;usersLoading=true;usersError='';render();try{let result;if(demo){result={total:3,server_time:now(),users:[{id:'demo-admin',email:'owner@example.com',is_admin:true,created_at:today+'T01:00:00+07:00',email_confirmed_at:today+'T01:01:00+07:00',last_seen_at:now(),last_data_update:now()},{id:'demo-user',email:'staff@example.com',is_admin:false,created_at:today+'T02:00:00+07:00',email_confirmed_at:today+'T02:01:00+07:00',last_seen_at:new Date(Date.now()-3600000).toISOString(),last_data_update:new Date(Date.now()-3500000).toISOString()},{id:'demo-pending',email:'newuser@example.com',is_admin:false,created_at:today+'T03:00:00+07:00',email_confirmed_at:null,last_seen_at:null,last_data_update:null}]};}else result=await RPOnline.users();if(!demo&&currentUser?.id!==ownerId)return;usersDirectory=result;}catch(error){if(!demo&&currentUser?.id!==ownerId)return;usersError=authMessage(error);}finally{if(demo||currentUser?.id===ownerId){usersLoading=false;if(page==='settings'&&settingsTab==='users')render();}}}
function settings(){let o=db.owner;let tabs='<div class="tabs">'+[['owner','ผู้ให้เช่าและรับเงิน'],['finance','ค่าปรับและภาษี'],...((demo||isRentAdmin)?[['users','ผู้ใช้งาน']]:[]),['cloud','การเชื่อมต่อข้อมูล'],['backup','สำรองและประวัติ']].map(([k,v])=>'<button data-setting="'+k+'" class="'+(settingsTab===k?'on':'')+'">'+v+'</button>').join('')+'</div>';if(settingsTab==='finance')return tabs+financeSettings();if(settingsTab==='users')return tabs+usersPanel();if(settingsTab==='owner')return tabs+panel('ข้อมูลที่แสดงในใบแจ้งค่าใช้จ่ายและใบเสร็จ','<div class="panel-body">'+dataForm('owner-form',field('ชื่อผู้ให้เช่า / นิติบุคคล (ใช้ในสัญญา)','name',o.name,'text','required')+field('ชื่อบริษัทบนหัวบิล','billCompany',o.billCompany||o.name,'text','required')+field('เลขประจำตัวผู้เสียภาษีบนหัวบิล','billTaxId',o.billTaxId||o.taxId||o.idcard||'')+field('สำนักงานใหญ่ / สาขาบนหัวบิล','billBranch',o.billBranch||'')+field('อัตรา VAT (%) สำหรับบิลใหม่','vatRate',o.vatRate??7,'number','min="0" max="100" required')+'<label class="field">ค่าเช่าในใบเสร็จ (ค่าเริ่มต้น)<select name="rentReceiptVat"><option value="none" '+(o.rentReceiptVat!=='included'?'selected':'')+'>ไม่ VAT</option><option value="included" '+(o.rentReceiptVat==='included'?'selected':'')+'>VAT รวมอยู่ในยอดค่าเช่าแล้ว</option></select></label>'+field('เลขประจำตัวประชาชน / เลขทะเบียนนิติบุคคล','idcard',o.idcard||o.taxId||'')+field('ผู้มีอำนาจลงนามฝ่ายผู้ให้เช่า','signer',o.signer||'')+field('ชื่อโครงการ','building',o.building)+field('เบอร์โทรศัพท์','phone',o.phone)+field('อีเมล (ไม่ใช้ให้กรอก —)','email',o.email,'text')+area('ที่อยู่ผู้ให้เช่า','address',o.address)+area('ที่ตั้งโครงการ','propertyAddr',o.propertyAddr)+area('ช่องทางชำระเงิน (ระบุธนาคาร ชื่อบัญชี และเลขบัญชี · แสดงในสัญญาและใบแจ้ง)','bank',o.bank))+'<div class="tools" style="margin-top:20px">'+btn('บันทึกข้อมูล','save-owner','primary')+'</div><p class="muted" style="font-size:10px;margin-top:15px">ชื่อบริษัท ที่อยู่ เลขผู้เสียภาษี และสาขา จะแสดงบนหัวเอกสาร · VAT แยกจากยอดรวม ไม่บวกซ้ำ · ใบแจ้งค่าใช้จ่ายและใบเสร็จที่บันทึกแล้วเก็บข้อมูล ณ วันออกเอกสาร</p></div>');if(settingsTab==='cloud')return tabs+panel('บัญชีและการซิงค์ออนไลน์','<div class="panel-body">'+(demo?'<div class="notice">ข้อมูลตัวอย่างแยกจากบัญชีจริง</div>':'<div class="notice '+(cloudError?'error':'')+'">'+E(cloudError||'ซิงค์อัตโนมัติเมื่อบันทึก ผู้ใช้งานที่ได้รับสิทธิ์ในโครงการเดียวกันจะเห็นข้อมูลชุดเดียวกัน')+'</div><p>บัญชี: <b>'+E(currentUser?.email||'')+'</b></p><div class="tools">'+btn('ซิงค์ตอนนี้','sync','primary')+(cloudError?btn('ใช้ข้อมูลออนไลน์ล่าสุด','load-latest'):'')+btn('ออกจากระบบ','logout')+'</div>')+'</div>');return tabs+panel('สำรองข้อมูลของโหมด'+(demo?'ตัวอย่าง':'จริง'),'<div class="panel-body"><div class="tools">'+btn('ดาวน์โหลดข้อมูลปัจจุบัน','export','primary')+'<label class="button">นำเข้าไฟล์สำรอง<input id="import" type="file" accept=".json,application/json" hidden></label></div><p class="muted" style="font-size:11px;line-height:1.9">ไฟล์สำรองมีข้อมูลผู้เช่าและสัญญา ควรเก็บไว้เป็นส่วนตัว<br>นำเข้าเฉพาะโหมดที่กำลังเปิด และตรวจรายการที่ขัดกันก่อนรวม</p></div>')+panel('ประวัติการทำรายการ','<div class="table-wrap"><table><thead><tr><th>วัน / เวลา</th><th>รายการ</th><th>อ้างอิง</th></tr></thead><tbody>'+db.rp3.audit.slice().reverse().slice(0,100).map(a=>'<tr><td>'+E(new Date(a.at).toLocaleString('th-TH'))+'</td><td>'+E(a.action)+'</td><td class="muted">'+E(a.ref||'—')+'</td></tr>').join('')+'</tbody></table></div>');}
function modal(title,body,footer='',wide=false){close();let el=document.createElement('div');el.className='modal-backdrop';el.id='modal';el.innerHTML='<section class="modal '+(wide?'wide':'')+'" role="dialog" aria-modal="true" aria-label="'+E(title)+'"><div class="modal-header"><h2>'+title+'</h2><button class="close" data-action="close" aria-label="ปิดหน้าต่าง">×</button></div><div class="modal-body">'+body+'</div>'+(footer?'<div class="modal-footer">'+footer+'</div>':'')+'</section>';document.body.appendChild(el);el.querySelector('input,select,button')?.focus();}
function close(){ $('modal')?.remove();modalData={};}
function detail(id){let i=db.rp3.invoices.find(x=>x.id===id);if(!i)return;let fee=LateTax.assessment(db,i,today);let receipts=db.rp3.receipts.filter(r=>r.invoiceId===id);let text='<div class="property-top"><div><h2>'+E(i.roomName)+'</h2><span class="muted">'+E(i.tenantName)+' · '+(i.serviceFrom?date(i.serviceFrom)+' – '+date(i.serviceTo):month(i.period))+'</span></div>'+tag(status(i))+'</div><div class="details-grid"><div><span class="key">เลขที่ใบแจ้งค่าใช้จ่าย</span><b>'+E(i.number)+'</b></div><div><span class="key">กำหนดชำระ</span><b>'+date(i.due)+'</b></div></div><table style="margin-top:20px"><thead><tr><th>รายการ</th><th class="num">จำนวนเงิน</th></tr></thead><tbody>'+[['ค่าเช่า',i.rent],['ค่าน้ำ',i.water],['ค่าไฟ',i.electric],[i.lateAssessments?.length?'ค่าปรับล่าช้า':'อื่น ๆ',i.other]].filter(x=>x[1]||(!i.category&&x[0]==='ค่าเช่า')).map(([label,v])=>'<tr><td>'+label+'</td><td class="num">'+M(v)+'</td></tr>').join('')+'</tbody></table><div class="invoice-total"><span>ยอดรวม '+M(i.total)+' บาท<br><small class="muted">ยอดคงเหลือ</small></span><strong>฿'+M(i.state==='void'?0:RP.balance(db,i))+'</strong></div>'+(i.snapshot?'<div class="two">'+['water','electric'].filter(k=>i.snapshot[k]).map(k=>{let s=i.snapshot[k];return '<div class="notice" style="font-size:11px">'+(k==='water'?'น้ำ':'ไฟ')+' · มิเตอร์ '+s.previous+' → '+s.current+'<br>'+s.units+' หน่วย × '+s.rate.toFixed(6)+' บาท<br><span class="muted" style="font-size:10px">รอบหลัก '+date(s.bill.from)+' – '+date(s.bill.to)+'</span></div>';}).join('')+'</div>':(i.category?'<p class="muted">'+(i.category==='penalty'?'ค่าปรับแยกจากบิลต้นทางตามรายละเอียดด้านล่าง':'บิลหมวดนี้ไม่ใช้เลขมิเตอร์')+'</p>':'<p class="muted">บิลจากระบบเดิม ไม่มีประวัติเลขมิเตอร์แนบ</p>'))+(fee?'<div class="notice">ค่าปรับคำนวณถึงวันนี้ '+M(fee.amount)+' บาท · '+fee.days+' วัน '+btn('ตรวจค่าปรับในบิลนี้','fee-preview','link','data-id="'+i.id+'"')+'</div>':'')+'<h3 style="font-size:13px">ประวัติรับชำระ</h3>'+(receipts.length?'<div class="timeline">'+receipts.map(r=>'<div><b>'+date(r.date)+' · '+M(r.amount)+' บาท</b> '+(r.voided?tag('ยกเลิกแล้ว'):'')+'<small>'+E(r.method)+' · '+E(r.note||'ไม่มีหมายเหตุ')+'</small><div class="tools" style="margin-top:7px;padding-bottom:0">'+(!r.voided?btn('ใบเสร็จ','print-receipt','small','data-id="'+r.id+'"')+btn('ยกเลิกการรับ','void-receipt','link','data-id="'+r.id+'"'):'')+(r.proof?btn('ดูหลักฐาน','view-proof','link','data-id="'+r.id+'"'):'')+'</div></div>').join('')+'</div>':'<p class="muted">ยังไม่มีรายการรับเงิน</p>')+(i.note?'<p class="muted">หมายเหตุ: '+E(i.note)+'</p>':'')+(i.state==='void'?'<div class="notice warn">ยกเลิกแล้ว: '+E(i.voidReason)+'</div>':'');modal('รายละเอียดใบแจ้งค่าใช้จ่าย',text+invoiceTaxNote(i),btn('พิมพ์ใบแจ้งค่าใช้จ่าย','print-invoice','','data-id="'+id+'"')+(i.state==='issued'&&!db.rp3.receipts.some(r=>r.invoiceId===id&&!r.voided)?btn('ปรับภาษีใบแจ้ง','invoice-tax-edit','','data-id="'+id+'"'):'')+(i.state==='issued'&&RP.balance(db,i)>0?btn('รับชำระ','receive','primary','data-id="'+id+'"'):'')+(i.state==='issued'?btn('ยกเลิกบิล','void-invoice','danger','data-id="'+id+'"'):''),true);}
const chargeLabels={rent:'ค่าเช่า',electric:'ค่าไฟฟ้า',water:'ค่าน้ำประปา',other:'ค่าใช้จ่ายอื่น ๆ',penalty:'ค่าปรับล่าช้า'};
function receiveModal(id){let i=db.rp3.invoices.find(x=>x.id===id);if(!i||i.state!=='issued'||RP.balance(db,i)<=0)throw Error('ใบแจ้งค่าใช้จ่ายนี้ไม่มีเงินค้างรับ');let pendingFee=LateTax.assessment(db,i,today),preview=db;let remaining=RP.remainingCharges(db,i),mode=i.accounting?.rentVatMode||'none';modal('รับชำระ · '+E(i.roomName),'<div class="notice">'+E(i.tenantName)+' · '+E(i.number)+(pendingFee?'<br>มีค่าปรับเพิ่มเติม '+M(pendingFee.amount)+' บาท · '+pendingFee.days+' วัน กรุณาปรับใบแจ้งก่อนรับยอดนี้ '+btn('ปรับใบแจ้งค่าปรับ','fee-preview','link','data-id="'+id+'"'):'')+'<br>ตรวจยอดเรียกเก็บ ค่าปรับ และภาษี ก่อนบันทึกรับชำระ · หากยังไม่จ่ายรายการใดให้ใส่ 0</div>'+dataForm('receive-form',RP.chargeKeys.filter(k=>remaining[k]>0).map(k=>field('ชำระ'+(k==='other'&&(pendingFee||i.lateAssessments?.length)?'ค่าปรับล่าช้า':chargeLabels[k])+' (ก่อนหักภาษี) · ค้าง '+M(remaining[k])+' บาท','paid_'+k,remaining[k],'number','min="0" max="'+remaining[k]+'" required')).join('')+'<input type="hidden" name="rentVatMode" value="'+E(mode)+'">'+withholdingFields(i,remaining)+field('วันที่รับเงินจริง','date',today,'date','max="'+today+'" required')+'<label class="field">ช่องทางชำระ<select name="method"><option>โอนเงิน</option><option>เงินสด</option><option>อื่น ๆ</option></select></label>'+field('เลขอ้างอิง / หมายเหตุ','note')+'<label class="field wide">แนบหลักฐานการชำระ · ไม่เกิน 5 MB<input type="file" data-file="proof" accept="image/png,image/jpeg,image/webp"></label>')+'<div class="invoice-total"><span>ยอดรับเงินจริงครั้งนี้</span><strong id="receive-total">฿'+M(RP.balance(preview,preview.rp3.invoices.find(x=>x.id===id)))+'</strong></div><p class="muted" id="receive-breakdown"></p><div id="proof-name" class="image-label"></div>',btn('ยกเลิก','close')+btn('บันทึกรับเงิน','save-receipt','primary','data-id="'+id+'"'));$('receive-form').dataset.invoiceId=id;updateWithholding();}
function receiveFirstRent(contractId,i){let c=db.contracts.find(c=>c.id===contractId),amount=DepositLedger.advanceRemaining(db,c,i);if(!(amount>0)){detail(i.id);return;}receiveModal(i.id);let f=$('receive-form');if(f.elements.paid_rent)f.elements.paid_rent.value=amount;if(f.elements.paid_other)f.elements.paid_other.value=0;updateWithholding();}
function receiptModal(id){let r=db.rp3.receipts.find(r=>r.id===id);if(!r||r.voided)throw Error('ไม่พบใบเสร็จที่ใช้งานได้');let i=db.rp3.invoices.find(i=>i.id===r.invoiceId),parts=r.allocations||RP.receiptAllocations(db,i).get(id);modal(i.category?'ใบเสร็จรับเงิน':'ใบเสร็จแยกประเภท','<div class="notice">รับเงินจริง '+M(LateTax.cash(r))+' บาท'+(r.withholding?.amount?' · ภาษีถูกหัก '+M(r.withholding.amount)+' บาท':'')+' · '+date(r.date)+'<br>เลือกเอกสารที่ต้องการตรวจและพิมพ์</div><div class="receipt-options">'+RP.chargeKeys.filter(k=>(parts[k]>0||i.lateAssessments?.length&&k===i.category&&parts.other>0)&&!(i.lateAssessments?.length&&k==='other')).map(k=>btn('ใบเสร็จ'+chargeLabels[k]+' · '+M(parts[k]+(i.lateAssessments?.length&&k===i.category?parts.other:0))+' บาท','preview-document','','data-id="'+i.id+'" data-receipt="'+id+'" data-kind="'+k+'"')).join('')+'</div>'+(!r.document?'<p class="muted">รายการรับเงินเดิม: แสดงยอดแยกตามลำดับ ค่าเช่า → ค่าไฟ → ค่าน้ำ → อื่น ๆ โดยไม่เปลี่ยนยอดรับเงินเดิม · ใช้ไม่ VAT สำหรับค่าเช่า</p>':''),btn('ปิด','close'));}
let documentExamples;
function exampleDocuments(){if(!demo)return;documentExamples=rentReadyDemo(today);let list=documentExamples.rp3.invoices.filter(i=>i.period===today.slice(0,7)&&i.roomId==='sample-room-1');modal('ตัวอย่างบิลแยก 3 ประเภท','<div class="notice">ตัวอย่างครบ 4 หลัง · รอบค่าเช่าเริ่มวันที่ 1 / 10 / 15 / 25 · ค่าน้ำและค่าไฟตามบิลหลักคนละรอบ · ชื่อบริษัทและข้อมูลทั้งหมดสมมติ</div><div class="receipt-options">'+list.map(i=>{let r=documentExamples.rp3.receipts.find(r=>r.invoiceId===i.id&&!r.voided);return btn('ใบแจ้ง'+chargeLabels[i.category],'preview-example','','data-id="'+i.id+'" data-kind=""')+btn('ใบเสร็จ'+chargeLabels[i.category],'preview-example','','data-id="'+i.id+'" data-receipt="'+r.id+'" data-kind="'+i.category+'"');}).join('')+'</div>',btn('ปิด','close'));}
function previewExample(id,receiptId,kind){if(!demo||!documentExamples)return;modal('ตัวอย่างเอกสาร','<div class="billing-preview">'+documentHTML(id,receiptId,kind,documentExamples)+'</div>',btn('เลือกเอกสารอื่น','example-documents')+btn('พิมพ์ / บันทึก PDF','print-example','primary','data-id="'+id+'" data-receipt="'+(receiptId||'')+'" data-kind="'+(kind||'')+'"'),true);}
