function tenantTaxFields(t={},prefix=''){let terms=InvoiceTax.tenantTerms(t);return '<fieldset class="wide tenant-tax-settings"><legend>เงื่อนไขภาษีสำหรับบิลใหม่</legend><p class="muted">ตั้งครั้งเดียว ระบบคำนวณตอนออกใบแจ้ง · ไม่หักภาษีให้ใส่ 0 · บิลและใบเสร็จที่ออกแล้วคงยอดเดิม</p><div class="form-grid"><label class="field">VAT ค่าเช่า<select name="'+prefix+'taxRentVatMode">'+[['','ใช้ค่าเริ่มต้นโครงการ'],['none','ไม่ VAT / ยกเว้น VAT'],['included','รวม VAT ในยอดแล้ว']].map(([v,label])=>'<option value="'+v+'" '+(terms.rentVatMode===v?'selected':'')+'>'+label+'</option>').join('')+'</select></label>'+[['whtRate','หัก ณ ที่จ่ายค่าเช่า (%)'],['waterWhtRate','หัก ณ ที่จ่ายค่าน้ำ (%)'],['electricWhtRate','หัก ณ ที่จ่ายค่าไฟ (%)']].map(([key,label])=>field(label,prefix+'tax_'+key,terms[key],'number','min="0" max="100" step="any" required')).join('')+'</div><small class="muted">VAT ค่าน้ำ–ค่าไฟแสดงตามต้นทุนบิลจริง · เงื่อนไขเฉพาะสัญญา (ถ้ามี) และการปรับเฉพาะใบแจ้งจะใช้ก่อนค่าเริ่มต้นนี้</small></fieldset>';}
function tenantFields(t={},prefix=''){let f=(label,key,value,required=false)=>field(label,prefix+key,value||'','text',required?'required':'');return '<label class="field">ประเภทผู้เช่า<select name="'+prefix+'entityType"><option value="unknown">ยังไม่ระบุ</option><option value="person" '+(t.entityType==='person'?'selected':'')+'>บุคคลธรรมดา</option><option value="company" '+(t.entityType==='company'?'selected':'')+'>บริษัท / นิติบุคคล</option></select></label>'+f('สำนักงานใหญ่ / รหัสสาขา','branch',t.branch)+f('ชื่อบุคคล / ชื่อกิจการ','fname',t.fname,true)+f('นามสกุล (ถ้ามี)','lname',t.lname)+f('เลขประจำตัวประชาชน / เลขทะเบียนนิติบุคคล','idcard',t.idcard||t.taxId||t.registrationNo||t.docno,true)+f('ผู้ลงนามฝ่ายผู้เช่า (บุคคลธรรมดาใช้ชื่อตนเอง)','signer',t.signer,true)+f('คำนำหน้า (ถ้ามี)','prefix',t.prefix)+f('เบอร์โทรศัพท์','phone',t.phone,true)+f('อีเมล (ไม่ใช้ให้กรอก —)','email',t.email,true)+f('LINE / ช่องทางติดต่อ (ถ้ามี)','line',t.line)+area('ที่อยู่ผู้เช่า',''+prefix+'address',t.address||t.addressId||'').replace('<textarea ','<textarea required ')+tenantTaxFields(t,prefix);}
