function fitOutFields(c){let enabled=c.rentFreeEnabled===true;return '<fieldset class="wide fitout-fields"><legend>ช่วงเข้าปรับปรุงพื้นที่ / ปลอดค่าเช่า</legend><label class="field">เงื่อนไข<select name="rentFreeEnabled"><option value="no" '+(!enabled?'selected':'')+'>ไม่มีช่วงปลอดค่าเช่า</option><option value="yes" '+(enabled?'selected':'')+'>มีช่วงเข้าปรับปรุงพื้นที่โดยไม่คิดค่าเช่า</option></select></label><div id="fitout-dates" '+(!enabled?'hidden':'')+'>'+field('เริ่มเข้าปรับปรุง / ส่งมอบพื้นที่','rentFreeFrom',c.rentFreeFrom||c.handoverDate||c.startDate||today,'date')+field('วันสุดท้ายที่ไม่คิดค่าเช่า','rentFreeTo',c.rentFreeTo||c.startDate||today,'date')+'</div><p id="fitout-summary" class="muted">ไม่มีช่วงปลอดค่าเช่า · เริ่มคิดค่าเช่าตามวันเริ่มสัญญา</p><small>ค่าน้ำ–ไฟคิดตามใช้จริงตั้งแต่วันส่งมอบพื้นที่ แม้อยู่ในช่วงปลอดค่าเช่า · วันสิ้นสุดสัญญาไม่เลื่อนอัตโนมัติ</small></fieldset>';}
function updateFitOutFields(){let form=$('contract-form');if(!form)return;let enabled=form.elements.rentFreeEnabled.value==='yes';$('fitout-dates').hidden=!enabled;try{let f=SplitBilling.fitOut({rentFreeEnabled:enabled,rentFreeFrom:form.elements.rentFreeFrom.value,rentFreeTo:form.elements.rentFreeTo.value,startDate:form.elements.startDate.value,endDate:form.elements.endDate.value});if(enabled)form.elements.handoverDate.value=f.from;form.elements.advancePeriod.value='ค่าเช่างวดแรก เริ่ม '+f.chargeFrom;$('fitout-summary').textContent=enabled?'ปลอดค่าเช่า '+f.days+' วัน · เริ่มคิดค่าเช่า '+date(f.chargeFrom):'ไม่มีช่วงปลอดค่าเช่า · เริ่มคิดค่าเช่า '+date(f.chargeFrom);}catch(error){$('fitout-summary').textContent=error.message;}}
function contractMeterFields(c){return '<section class="contract-meters wide" aria-label="ข้อมูลมิเตอร์ ณ วันส่งมอบ">'+[['water','น้ำ','WM-001'],['electric','ไฟฟ้า','EM-001']].map(([key,title,example])=>'<fieldset class="contract-meter"><legend>มิเตอร์'+title+'</legend>'+field('รหัสประจำตัวมิเตอร์'+title,key+'MeterNo',c[key+'MeterNo']||'','text','aria-describedby="'+key+'-id-help" placeholder="เช่น '+example+'"')+'<small id="'+key+'-id-help">รหัสที่ติดบนตัวเครื่อง เช่น '+example+'</small>'+field('เลขหน่วยบนหน้าปัด ณ วันส่งมอบ',key+'Start',c[key+'Start']??'','number','min="0" aria-describedby="'+key+'-reading-help" placeholder="เช่น 1250"')+'<small id="'+key+'-reading-help">หน่วยสะสมที่อ่านได้ เช่น 1,250 หน่วย · ใช้เป็นค่าเริ่มต้นการเช่า</small></fieldset>').join('')+'</section>';}
function contractModal(id,roomId){let c=db.contracts.find(c=>c.id===id)||{},newTenant=!id;let tenantOptions=db.tenants.filter(t=>!t.archived||t.id===c.tenantId).map(t=>'<option value="'+t.id+'" '+(c.tenantId===t.id?'selected':'')+'>'+E(tenant(t.id))+'</option>').join('');let r=db.rooms.find(r=>r.id===(c.roomId||roomId));modal(id?'แก้ไขสัญญา · '+E(r?.name):'ผู้เช่าและสัญญา · '+E(r?.name),dataForm('contract-form','<label class="field wide">ผู้เช่า<select name="tenantId">'+(newTenant?'<option value="new">เพิ่มผู้เช่าใหม่</option>':'')+tenantOptions+'</select></label><section class="contract-tenant wide"><h3>ข้อมูลผู้เช่า</h3><p class="muted">กรอกครั้งเดียว บันทึกพร้อมสัญญา และนำไปเติมในเอกสารอัตโนมัติ</p><div id="contract-tenant-fields" class="form-grid">'+tenantFields(db.tenants.find(t=>t.id===c.tenantId)||{},'tenant_')+'</div></section>'+field('เลขที่สัญญา (รันอัตโนมัติ)','number',c.number||LeaseFields.nextNumber(db,c.signedDate||c.startDate||today),'text','readonly')+field('วันทำสัญญา','signedDate',c.signedDate||c.startDate||today,'date')+'<label class="field">ระยะเวลาสัญญา<select name="termYears" id="f-termYears">'+[1,2,3].map(n=>'<option value="'+n+'" '+(LeaseFields.inferYears(c)===n?'selected':'')+'>'+n+' ปี</option>').join('')+'</select></label>'+field('วันเริ่มสัญญา','startDate',c.startDate||today,'date','required')+field('วันสิ้นสุดสัญญา (คำนวณอัตโนมัติ)','endDate',LeaseFields.endDate(c.startDate||today,LeaseFields.inferYears(c)),'date','readonly required')+fitOutFields(c)+field('ค่าเช่าตามสัญญา (บาท)','rent',c.rent??r?.rent??0,'number','min="0" required')+field('เงินประกัน (บาท)','deposit',c.deposit||0,'number','min="0"')+field('ค่าเช่าล่วงหน้างวดแรก (บาท)','advance',c.advance||0,'number','min="0"')+'<div class="notice wide" style="grid-column:1/-1">ค่าเช่าล่วงหน้าใช้ชำระค่าเช่างวดแรก ไม่เก็บซ้ำ · เงินประกันแยกตามสัญญา · เงินประกันรวมล่วงหน้าไม่เกินค่าเช่า 3 เดือน</div>'+field('วันครบกำหนดเดิม (ใช้เมื่อเลือกคงวันเดิม)','dueDay',c.dueDay||10,'number','min="1" max="31" step="1" required')+ '<label class="field">รอบค่าเช่าและกำหนดชำระ<select name="billingSchedule"><option value="legacy" '+(id&&c.billingSchedule!=='anniversary'?'selected':'')+'>รอบตามวันเริ่มสัญญา · คงวันครบกำหนดเดิม</option><option value="anniversary" '+(!id||c.billingSchedule==='anniversary'?'selected':'')+'>ชำระวันเริ่มแต่ละรอบสัญญา</option></select></label>'+field('ค่าน้ำ / ไฟครบกำหนดหลังสิ้นรอบกี่วัน','utilityDueDays',c.utilityDueDays??7,'number','min="0" max="60" required')+field('สถานที่ทำสัญญา','madeAt',c.madeAt||'')+'<label class="field">ค่าเช่า รวม / ไม่รวม VAT<select name="rentVatMode"><option value="">เลือกตามข้อตกลง</option><option value="รวม" '+(c.rentVatMode==='รวม'?'selected':'')+'>รวม VAT (หากมีตามกฎหมาย)</option><option value="ไม่รวม" '+(c.rentVatMode==='ไม่รวม'?'selected':'')+'>ไม่รวม VAT (หากมีตามกฎหมาย)</option></select></label>'+field('งวดค่าเช่าที่ชำระล่วงหน้า','advancePeriod','ค่าเช่างวดแรก เริ่ม '+(c.startDate||today),'text','readonly')+field('ผู้มีอำนาจลงนามฝ่ายผู้ให้เช่า (ถ้าต่างจากตั้งค่า)','ownerSigner',c.ownerSigner||'')+field('ผู้มีอำนาจลงนามฝ่ายผู้เช่า (ถ้าต่างจากข้อมูลผู้เช่า)','tenantSigner',c.tenantSigner||'')+field('พยานคนที่ 1','witness1',c.witness1||'')+field('พยานคนที่ 2','witness2',c.witness2||'')+'<label class="field wide" style="display:flex;flex-direction:row;align-items:center"><input name="attachUtilities" type="checkbox" style="width:auto" '+(c.attachUtilities!==false?'checked':'')+'>แนบข้อมูลมิเตอร์ ณ วันส่งมอบ และวิธีคิดค่าน้ำ–ค่าไฟ</label>'+field('วันส่งมอบพื้นที่','handoverDate',c.handoverDate||c.startDate||today,'date')+field('ผู้ประสานงานฝ่ายผู้เช่า','tenantContact',c.tenantContact||'')+field('วัตถุประสงค์การเช่า','permittedUse',c.permittedUse||c.purpose||'เพื่อประกอบธุรกิจ')+field('ผู้ประสานงานฝ่ายผู้ให้เช่า','ownerContact',c.ownerContact||'')+contractMeterFields(c)+area('บันทึกภายใน (ไม่แทรกในสัญญาฉบับเต็ม)','terms',c.terms))+'<p class="muted" style="font-size:10px">วันสิ้นสุดนับถึงวันก่อนวันครบรอบ เช่น เริ่ม 15/11/2569 ทำ 1 ปี สิ้นสุด 14/11/2570 · ค่าน้ำ–ค่าไฟคิดตามทุนบิลจริง · เอกสารที่ออกแล้วเก็บข้อมูลเดิมไว้</p>',btn('ยกเลิก','close')+btn('บันทึกผู้เช่าและสัญญา','save-contract','primary','data-id="'+(id||'')+'" data-roomid="'+(c.roomId||roomId)+'"'),true);$('contract-form').dataset.contractId=id||'';updateFitOutFields();}
function reasonModal(title,action,id,text){modal(title,'<div class="notice warn">'+E(text)+'</div>'+dataForm('reason-form',area('เหตุผล (จำเป็น)','reason','')),btn('ย้อนกลับ','close')+btn('ยืนยัน','confirm-'+action,'danger','data-id="'+id+'"'));}
function collectLeaseDocuments(){if(!modalData.annexDocuments)return;document.querySelectorAll('[data-annex-text]').forEach(el=>{let item=modalData.annexDocuments[el.dataset.annexText]||(modalData.annexDocuments[el.dataset.annexText]={files:[]});item.text=el.value;});}
function renderLeaseDocumentFiles(){for(let [key] of LeaseExtras.topics){let el=$('annex-files-'+key);if(!el)continue;let files=modalData.annexDocuments[key]?.files||[];el.innerHTML=files.map((f,index)=>'<div class="annex-file-row"><span>'+E(f.name)+(f.pages?' · '+f.pages.length+' หน้า':'')+'</span><div>'+btn('ดูต้นฉบับ','view-annex-file','small','data-key="'+key+'" data-index="'+index+'"')+btn('นำออก','remove-annex-file','small danger','data-key="'+key+'" data-index="'+index+'"')+'</div></div>').join('');}}
function leaseDocumentsModal(id){let c=db.contracts.find(c=>c.id===id);if(!c)throw Error('ไม่พบสัญญา');modal('เอกสารประกอบสัญญา · '+E(c.number),'<div class="notice">กรอกเนื้อหาหรือแนบไฟล์ตามหัวข้อ ระบบติ๊กในรายการท้ายสัญญาและรวมในเอกสารให้เอง · PDF / PNG / JPEG / WebP ไม่เกิน 5 MB ต่อไฟล์'+(c.leaseDocument?'<br>เอกสารที่ออกแล้วเก็บฉบับเดิม กด “เตรียมออกฉบับใหม่” เพื่อใช้ข้อมูลชุดใหม่':'')+'</div><div id="annex-upload-status" role="status"></div>'+LeaseExtras.topics.map(([key,index,title])=>'<section class="annex-editor"><h3>'+E(title)+'</h3><label class="field">รายละเอียด (ไม่บังคับ)<textarea data-annex-text="'+key+'" maxlength="6000">'+E(c.annexDocuments?.[key]?.text||'')+'</textarea></label><label class="field">แนบไฟล์ (เลือกหลายไฟล์ได้)<input type="file" data-annex-upload="'+key+'" accept="application/pdf,image/png,image/jpeg,image/webp" multiple></label><div id="annex-files-'+key+'"></div></section>').join(''),btn('ยกเลิก','close')+btn('บันทึกเอกสารแนบท้าย','save-lease-documents','primary','data-id="'+id+'"'),true);modalData.annexDocuments=C(c.annexDocuments||{});modalData.documentContract=id;renderLeaseDocumentFiles();}
async function uploadLeaseDocuments(input){let target=modalData;if(target.loading)throw Error('รออ่านไฟล์ก่อน');collectLeaseDocuments();let key=input.dataset.annexUpload,files=Array.from(input.files||[]),current=target.annexDocuments[key]||{text:'',files:[]};if((current.files||[]).length+files.length>10)throw Error('แนบได้ไม่เกิน 10 ไฟล์ต่อหัวข้อ');target.loading=true;$('annex-upload-status').textContent='กำลังอ่านไฟล์และเตรียมหน้าพิมพ์…';try{let incoming=[];for(let f of files)incoming.push(await LeaseExtras.readFile(f,uid));if(target!==modalData)return;collectLeaseDocuments();let item=target.annexDocuments[key]||(target.annexDocuments[key]={text:'',files:[]});item.files=(item.files||[]).concat(incoming);renderLeaseDocumentFiles();}finally{target.loading=false;if(target===modalData){$('annex-upload-status').textContent='';input.value='';}}}
function openAnnexFile(file){if(!file||!/^data:(?:image\/(?:png|jpeg|webp)|application\/pdf);base64,/.test(file.data||''))throw Error('ไม่พบไฟล์ต้นฉบับ');let [head,body]=file.data.split(','),bytes=Uint8Array.from(atob(body),c=>c.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:file.type||'application/pdf'})),link=document.createElement('a');link.href=url;link.download=file.name;link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
const photoCategories={building:'สภาพอาคาร',water:'มิเตอร์น้ำ',electric:'มิเตอร์ไฟฟ้า'};
function photoOptions(value){return Object.entries(photoCategories).map(([k,label])=>'<option value="'+k+'" '+(k===value?'selected':'')+'>'+label+'</option>').join('');}
function collectLeasePhotos(){if(!modalData.handoverPhotos)return;document.querySelectorAll('[data-lease-photo-row]').forEach(row=>{let photo=modalData.handoverPhotos[Number(row.dataset.leasePhotoRow)];photo.category=row.querySelector('[name="photoCategory"]').value;photo.date=row.querySelector('[name="photoDate"]').value;photo.caption=row.querySelector('[name="photoCaption"]').value;});}
function renderLeasePhotos(){let el=$('lease-photo-list');if(!el)return;el.innerHTML=modalData.handoverPhotos.length?modalData.handoverPhotos.map((photo,index)=>'<article class="handover-photo-card" data-lease-photo-row="'+index+'"><img src="'+E(/^data:image\/(png|jpeg|webp);base64,/.test(photo.data||'')?photo.data:'')+'" alt="รูปส่งมอบ '+(index+1)+'"><div><label class="field">หมวดภาพ<select name="photoCategory">'+photoOptions(photo.category)+'</select></label>'+field('วันที่ถ่ายภาพ','photoDate',photo.date,'date','required')+field('คำอธิบายภาพ (เก็บในระบบ)','photoCaption',photo.caption||'','text','maxlength="300"')+'<small>'+E(photo.name)+'</small><div class="tools">'+btn('นำรูปนี้ออก','remove-lease-photo','small danger','data-index="'+index+'"')+'</div></div></article>').join(''):'<div class="empty">ยังไม่มีรูปแนบ เลือกหมวดและไฟล์ภาพด้านบนเพื่อเพิ่ม</div>';}
function leasePhotosModal(id){let c=db.contracts.find(x=>x.id===id);if(!c)throw Error('ไม่พบสัญญา');modal('รูปส่งมอบ / เอกสารแนบท้าย · '+E(c.number),'<div class="notice">แนบรูปสภาพอาคารและรูปมิเตอร์น้ำ–ไฟ รูปอาคาร 2 รูปต่อหน้า · รูปมิเตอร์น้ำ + รูปมิเตอร์ไฟ อยู่ด้วยกันใน 1 หน้า · แสดงข้อมูลตามหัวข้อ และเซ็นครั้งเดียวท้ายชุดรูปแนบ'+(c.leaseDocument?'<br>สัญญาที่ออกไว้จะเก็บรูปเดิม หากต้องการรูปชุดนี้ในสัญญา ให้กด “เตรียมออกฉบับใหม่” หลังบันทึก':'')+'</div>'+dataForm('lease-photo-form','<label class="field">หมวดภาพที่จะเพิ่ม<select name="category">'+photoOptions('building')+'</select></label>'+field('วันที่ถ่ายภาพ','date',c.handoverDate||c.startDate||today,'date','required')+field('คำอธิบายภาพที่จะเพิ่ม (เก็บในระบบ)','caption','','text','maxlength="300"')+'<label class="field">เลือกรูป (เลือกหลายไฟล์ได้)<input id="lease-photo-files" type="file" accept="image/jpeg,image/png,image/webp" multiple></label><p class="muted wide">PNG / JPEG / WebP ไม่เกิน 5 MB ต่อรูป · ไม่เกิน 20 รูปต่อสัญญา · กดบันทึกเมื่อเพิ่มและตรวจรูปครบแล้ว</p><p id="lease-photo-loading" class="wide" role="status"></p><div id="lease-photo-list" class="wide"></div>'),btn('ยกเลิก','close')+btn('บันทึกรูปแนบ','save-lease-photos','primary','data-id="'+id+'"'),true);modalData.handoverPhotos=C(c.handoverPhotos||[]);modalData.photoContract=id;renderLeasePhotos();}
async function uploadLeasePhotos(input){let target=modalData,files=Array.from(input.files||[]);if(!files.length)return;if(target.loading)throw Error('รออ่านรูปให้เสร็จก่อน');collectLeasePhotos();if(target.handoverPhotos.length+files.length>20)throw Error('แนบได้ไม่เกิน 20 รูปต่อสัญญา');for(let f of files)if(f.size>5*1024*1024||!['image/png','image/jpeg','image/webp'].includes(f.type))throw Error('ใช้ภาพ PNG / JPEG / WebP ไม่เกิน 5 MB ต่อรูป');let form=$('lease-photo-form'),category=form.elements.category.value,date=form.elements.date.value,caption=form.elements.caption.value.trim();if(!date)throw Error('ระบุวันที่ถ่ายภาพก่อน');target.loading=true;$('lease-photo-loading').textContent='กำลังอ่านรูป…';try{let photos=[];for(let file of files){let data=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('อ่านไฟล์ไม่สำเร็จ'));r.readAsDataURL(file);});let probe=new Image();probe.src=data;await probe.decode().catch(()=>{throw Error('เปิดภาพ '+file.name+' ไม่สำเร็จ');});let assetId=crypto.subtle?Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer())),b=>b.toString(16).padStart(2,'0')).join(''):uid();photos.push({id:uid(),category,date,caption,name:file.name,assetId,data});}if(target!==modalData)return;collectLeasePhotos();target.handoverPhotos.push(...photos);renderLeasePhotos();}finally{target.loading=false;if(target===modalData){$('lease-photo-loading').textContent='';input.value='';}}}
function imageModal(image){if(!image||!/^data:image\/(png|jpeg|webp);base64,/.test(image.data))throw Error('ไม่พบภาพที่เปิดได้');modal('ภาพแนบ · '+E(image.name),'<img class="image-preview" alt="ภาพบิลหรือหลักฐานที่แนบ" src="'+E(image.data)+'">',btn('ปิด','close'),true);}
function draftSave(){let c=getWorking(),idx=db.rp3.cycles.findIndex(x=>x.id===c.id);if(idx>=0)db.rp3.cycles[idx]=C(c);else db.rp3.cycles.push(C(c));cacheDraft();save('บันทึกร่างบิลรายเดือน',c.id);toast('บันทึกร่างแล้ว');}
function issuePreview(){if(!(db.owner.billCompany||db.owner.name||'').trim())throw Error('กรอกชื่อบริษัทบนหัวบิลในหน้าตั้งค่าก่อนออกใบแจ้งค่าใช้จ่าย');let c=getWorking(),built=RentModel.build(db,c,uid,now());modal('ยืนยันออกใบแจ้งค่าใช้จ่าย','<div class="notice">รอบ '+month(period)+' · '+built.invoices.length+' หลัง<br>รวมเรียกเก็บ <b>'+M(built.invoices.reduce((s,i)=>s+i.total,0))+' บาท</b><br>หัก ณ ที่จ่ายที่แจ้ง '+M(built.invoices.reduce((n,i)=>n+(i.taxPlan?.withholding.amount||0),0))+' บาท<br>สุทธิให้ชำระ <b>'+M(built.invoices.reduce((n,i)=>n+(i.taxPlan?.netDue??i.total),0))+' บาท</b><br>หลังยืนยัน ระบบจะเก็บยอด ช่วงวันที่ และวิธีคำนวณของบิลนี้</div>',btn('กลับไปตรวจ','close')+btn('ออกใบแจ้งค่าใช้จ่าย','confirm-issue','primary'));}
function documentHTML(invoiceId,receiptId,kind,records=db){
let i=records.rp3.invoices.find(i=>i.id===invoiceId),r=receiptId&&records.rp3.receipts.find(r=>r.id===receiptId&&r.invoiceId===invoiceId);if(!i||receiptId&&(!r||r.voided))return '';
let o=r?.document?.owner||i.owner||records.owner,t=r?.document?.tenant||i.tenant||{},rate=RentModel.vatRate(i.accounting?.vatRate??7),mode=i.accounting?.rentVatMode||'none',parts;
if(r){let allocated=r.allocations||RP.receiptAllocations(records,i).get(r.id);parts=r.document?.parts||Object.fromEntries(RP.chargeKeys.map(k=>[k,RentModel.taxPart(allocated[k]||0,k==='rent'||k==='other'?'none':'included',rate)]));if(!kind)return RP.chargeKeys.filter(k=>parts[k]?.total>0).map(k=>documentHTML(invoiceId,receiptId,k,records)).join('');if(!RP.chargeKeys.includes(kind)||!parts[kind]||parts[kind].total<=0&&!(i.lateAssessments?.length&&kind===i.category&&parts.other?.total>0))return '';}
else parts=Object.fromEntries(RP.chargeKeys.map(k=>[k,RentModel.taxPart(i[k]||0,k==='rent'?mode:k==='other'?'none':'included',rate)]));
let rows=r?[[i.category==='penalty'?'ค่าปรับล่าช้า':chargeLabels[kind],parts[kind]],...(i.lateAssessments?.length&&kind===i.category&&parts.other?.total>0?[['ค่าปรับล่าช้า',parts.other]]:[])].filter(x=>x[1].total>0):RP.chargeKeys.filter(k=>parts[k].total||(!i.category&&k==='rent')).map(k=>[k==='other'&&i.lateAssessments?.length?'ค่าปรับล่าช้า':chargeLabels[k],parts[k]]),net=RP.money(rows.reduce((sum,x)=>sum+x[1].net,0)),vat=RP.money(rows.reduce((sum,x)=>sum+x[1].vat,0)),total=r?RP.money(rows.reduce((n,x)=>n+x[1].total,0)):i.total,number=r?r.number+'-'+({rent:'RENT',electric:'ELEC',water:'WATER',other:'OTHER'}[kind]):i.number;
let title=r?'ใบเสร็จ'+(i.category==='penalty'?'ค่าปรับล่าช้า':chargeLabels[kind]):'ใบแจ้ง'+(chargeLabels[i.category]||'ค่าใช้จ่าย')+(i.state==='void'?' (ยกเลิก)':''),s=i.snapshot?.[kind],billName=o.billCompany||o.name||'ยังไม่ได้ตั้งชื่อบริษัท';
let utility=(r||i.category==='water'||i.category==='electric')&&RentModel.utilityBreakdown(i,kind||i.category,parts[kind||i.category]),utilityHTML='';
if(utility){let u=utility,utilityKind=kind||i.category,unit=utilityKind==='electric'?'kWh':'ลบ.ม.';utilityHTML='<section class="utility-detail"><h3>รายละเอียด'+chargeLabels[kind||i.category]+'</h3><div class="utility-readings"><div><span>เลขมิเตอร์</span><b>'+E(u.meterNo||'—')+'</b></div><div><span>รอบการใช้</span><b>'+date(u.from)+' – '+date(u.to)+'</b></div><div><span>เลขอ่านครั้งก่อน</span><b>'+E(u.previous)+'</b></div><div><span>เลขอ่านครั้งนี้</span><b>'+E(u.current)+'</b></div><div><span>จำนวนที่ใช้</span><b>'+E(u.units)+' '+unit+'</b></div><div><span>บิลหลักอ้างอิง</span><b>'+E(u.reference||'—')+'</b></div></div><p class="utility-allocation">จัดสรรตามการใช้ '+E(u.units)+' / '+E(u.masterUnits)+' '+unit+' ของบิลหลัก'+(u.partial?'<br>ชำระบางส่วน '+M(u.total)+' จาก '+M(u.fullTotal)+' บาท · รายละเอียดด้านล่างเฉพาะยอดรับครั้งนี้':'')+'</p><table class="utility-lines"><thead><tr><th>รายละเอียดค่าใช้จ่าย</th><th class="num">จำนวนเงิน (บาท)</th></tr></thead><tbody>'+u.items.map(row=>'<tr><td>'+E(row.label)+(row.rate!==null?'<small>ต้นทุนจากบิลหลัก '+row.rate.toFixed(6)+' บาท / '+unit+'</small>':'')+'</td><td class="num">'+M(row.amount)+'</td></tr>').join('')+'</tbody></table></section>';}
return '<article class="billing-sheet">'+(demo?'<div class="demo-watermark">ข้อมูลตัวอย่าง · ไม่ใช่เอกสารเรียกเก็บเงินจริง</div>':'')+'<header class="billing-head"><div><h2 class="bill-company">'+E(billName)+'</h2><div>'+E(o.address||'')+'</div><div>เลขประจำตัวผู้เสียภาษี '+E(o.billTaxId||o.taxId||o.idcard||'—')+' '+E(o.billBranch||'')+'</div><div>โทร '+E(o.phone||'—')+(o.building?' · '+E(o.building):'')+'</div></div><div class="bill-title"><h1>'+title+'</h1><div>เลขที่ '+E(number)+(i.documentRevisions?.length&&!r?' · ปรับปรุงครั้งที่ '+i.documentRevisions.length:'')+'</div><div>วันที่ '+date(r?r.date:i.createdAt)+'</div><div>รอบ '+(i.serviceFrom?date(i.serviceFrom)+' – '+date(i.serviceTo):month(i.period))+'</div></div></header><div class="bill-customer"><b>ผู้เช่า '+E(i.tenantName)+' · '+E(i.roomName)+'</b><div>'+E(t.address||'')+'</div><div>เลขประจำตัวผู้เสียภาษี / เลขประจำตัว '+E(t.idcard||t.taxId||'—')+'</div><div>'+(r?'อ้างอิงใบแจ้งค่าใช้จ่าย '+E(i.number)+' · '+E(r.method):'กำหนดชำระ '+date(i.due))+'</div></div>'+(utility?utilityHTML+(i.lateAssessments?.length&&parts.other?.total>0?'<p>ค่าปรับล่าช้า '+M(parts.other.total)+' บาท</p>':''):'<table><thead><tr><th>รายการ</th><th class="num">ก่อน VAT</th><th class="num">VAT</th><th class="num">รวม (บาท)</th></tr></thead><tbody>'+rows.map(([label,p])=>'<tr><td>'+label+'<small>'+(p.mode==='included'?'รวม VAT '+p.rate+'% แล้ว':'ไม่ VAT')+'</small></td><td class="num">'+M(p.net)+'</td><td class="num">'+M(p.vat)+'</td><td class="num">'+M(p.total)+'</td></tr>').join('')+'</tbody></table>')+'<div class="bill-summary"><div><span>รวมก่อน VAT</span><b>'+M(net)+'</b></div><div><span>VAT'+(parts[kind||i.category]?.mode==='included'?' '+parts[kind||i.category].rate+'%':'')+'</span><b>'+M(vat)+'</b></div><div class="bill-grand"><span>'+(r?(r.withholding?.amount?'ยอดชำระ':'รับเงิน')+(i.category==='penalty'?'ค่าปรับล่าช้า':chargeLabels[kind])+'ครั้งนี้':'รวมค่าใช้จ่าย')+'</span><b>'+M(total)+' บาท</b></div></div>'+(s?.bill&&!utility?'<p>มิเตอร์ '+E(s.previous)+' → '+E(s.current)+' · ใช้ '+E(s.units)+' หน่วย<br>รอบมิเตอร์ '+date(s.bill?.from)+' – '+date(s.bill?.to)+'</p>':'')+(!r&&i.taxPlan?'<div class="invoice-tax-totals"><div><span>หัก ณ ที่จ่ายที่คาดไว้ '+i.taxPlan.withholding.rate+'% (ฐาน '+M(i.taxPlan.withholding.base)+' บาท)</span><b>− '+M(i.taxPlan.withholding.amount)+'</b></div><div class="net-remittance"><span>ยอดสุทธิให้ชำระ</span><b>'+M(i.taxPlan.netDue)+' บาท</b></div><small>ผู้จ่ายหักภาษีเมื่อชำระเงินจริง และส่งหนังสือรับรองหัก ณ ที่จ่าย</small></div>':'')+(i.latePolicy?'<p class="bill-late-terms">ค่าปรับ: '+(i.latePolicy.enabled?'ผ่อนผัน '+i.latePolicy.grace+' วันหลังครบกำหนด ตั้งแต่วันที่ '+(Number(i.latePolicy.grace)+1)+' '+(i.latePolicy.mode==='daily'?'วันละ '+M(i.latePolicy.rate)+' บาท':'อัตรา '+i.latePolicy.rate+'% ต่อปีจากยอดค้างจริง')+' ไม่คิดย้อนหลังช่วงผ่อนผัน':'ไม่เรียกค่าปรับ')+'</p>':'')+'<p>'+(i.taxPlan&&!r?'ยอดคงเหลือสุทธิให้ชำระ '+M(i.state==='void'?0:InvoiceTax.cashDue(records,i))+' บาท':'ยอดคงเหลือปัจจุบันของใบแจ้งค่าใช้จ่าย '+M(i.state==='void'?0:RP.balance(records,i))+' บาท')+'</p>'+(!r?'<p>บัญชีรับชำระ '+E(o.bank||'—')+'</p>':'')+((r?r.note:i.note)?'<p>หมายเหตุ: '+E(r?r.note||'':i.note||'')+'</p>':'')+(r&&r.withholding?.amount?'<div class="notice">ยอดชำระหนี้ครั้งนี้ '+M(r.amount)+' บาท · ภาษีถูกหัก ณ ที่จ่าย '+M(r.withholding.amount)+' บาท · รับเงินจริง '+M(LateTax.cash(r))+' บาท<br>หนังสือรับรอง '+E(r.withholding.certificateNumber||'รอรับเอกสาร')+'</div>':'')+'<div class="sign"><span>ผู้'+(r?'รับเงิน':'ออกเอกสาร')+' ................................</span><span>วันที่ ................................</span></div><footer>ค่าน้ำ–ค่าไฟตามต้นทุนบิลจริง · VAT แสดงแยกจากยอดรวม ไม่บวกซ้ำ<br>เอกสารนี้เป็น'+(r?'ใบเสร็จรับเงิน':'ใบแจ้งค่าใช้จ่าย')+' ไม่ใช่ใบกำกับภาษี</footer></article>';
}
function printDocument(invoiceId,receiptId,kind){let html=documentHTML(invoiceId,receiptId,kind);if(!html)return;$('print').innerHTML=html;window.print();}

function updateContractDates(){let form=$('contract-form');if(!form)return;let end=LeaseFields.endDate(form.elements.startDate.value,Number(form.elements.termYears.value));form.elements.endDate.value=end;let id=form.dataset.contractId;if(!id||!db.contracts.find(c=>c.id===id)?.number)form.elements.number.value=LeaseFields.nextNumber(db,form.elements.signedDate.value||today);}
async function fullLease(id,fresh=false){let c=db.contracts.find(c=>c.id===id);if(!c)throw Error('ไม่พบสัญญา');let saved=!!c.leaseDocument&&!fresh,snapshot=saved?c.leaseDocument:WarehouseLease.build(db,c,{demo}),pages=await WarehouseLease.paginate(snapshot,E);let warning=snapshot.missing.length?'<div class="notice warn"><b>ข้อมูลยังไม่ครบ '+snapshot.missing.length+' รายการ</b><br>'+snapshot.missing.map(E).join(' · ')+'<div class="tools" style="margin-top:10px">'+btn('ข้อมูลผู้ให้เช่า','edit-owner-for-lease','small')+btn('ข้อมูลผู้เช่า','edit-tenant','small','data-id="'+c.tenantId+'"')+btn('ข้อมูลสัญญา','edit-contract','small','data-id="'+id+'"')+'</div></div>':'<div class="notice">'+(saved?'เอกสารที่ออกไว้เมื่อ '+date(snapshot.issuedAt||snapshot.generatedAt)+' · เก็บข้อความและข้อมูล ณ วันออกเอกสาร':'ข้อมูลช่องกรอกครบแล้ว · ตรวจเนื้อหาก่อนออกสัญญาฉบับเต็ม')+'</div>';modal('สัญญาฉบับเต็ม · '+E(snapshot.number),warning+'<div class="lease-preview"><div class="lease-pages">'+pages+'</div></div>',btn('ปิด','close')+btn('เอกสารแนบท้าย','lease-documents','','data-id="'+id+'"')+btn('แนบรูปส่งมอบ','lease-photos','','data-id="'+id+'"')+(saved?btn('เตรียมออกฉบับใหม่','fresh-lease','','data-id="'+id+'"'):btn('ออกสัญญาฉบับเต็ม','issue-lease','primary','data-id="'+id+'" '+(snapshot.missing.length?'disabled':'')))+btn(saved?'พิมพ์ / บันทึก PDF':snapshot.missing.length?'พิมพ์ร่าง':'พิมพ์เพื่อตรวจ','print-lease','','data-id="'+id+'" data-fresh="'+(!saved)+'"'),true);modalData.leaseSnapshot=snapshot;modalData.leaseContract=id;}
async function issueLease(id){let c=db.contracts.find(c=>c.id===id);if(!c)throw Error('ไม่พบสัญญา');let snapshot=WarehouseLease.build(db,c,{demo});if(snapshot.missing.length)throw Error('กรอกข้อมูลให้ครบก่อนออกสัญญา: '+snapshot.missing.join(', '));if(c.leaseDocument)db.rp3.audit.push({id:uid(),at:now(),action:'เก็บสัญญาฉบับก่อนออกเอกสารใหม่',ref:c.id,before:C(c.leaseDocument)});snapshot.issuedAt=now();c.leaseDocument=snapshot;save('ออกสัญญาฉบับเต็มตามต้นฉบับ',c.id);await fullLease(id);toast('ออกสัญญาฉบับเต็มแล้ว พร้อมพิมพ์หรือบันทึก PDF');}
async function printLease(id,fresh=false){let c=db.contracts.find(c=>c.id===id);if(!c)throw Error('ไม่พบสัญญา');let snapshot=!fresh&&c.leaseDocument?c.leaseDocument:WarehouseLease.build(db,c,{demo}),pages=await WarehouseLease.paginate(snapshot,E);$('print').innerHTML='<div class="lease-pages">'+pages+'</div>';await Promise.all(Array.from($('print').querySelectorAll('img')).map(img=>{img.loading='eager';return img.decode();}));document.body.classList.add('printing-lease');let printStyle=document.createElement('style');printStyle.id='lease-print-page';printStyle.textContent='@page { size: A4 portrait; margin: 0; }';$('lease-print-page')?.remove();document.head.appendChild(printStyle);window.print();}
