async function sync(){if(demo||!currentUser)throw Error('เข้าสู่ระบบก่อนซิงค์ข้อมูล');if(busy)throw Error('กำลังซิงค์ข้อมูล กรุณารอสักครู่');let syncOwner=currentUser.id;busy=true;cloudError='';renderStatus();try{await rpStore.flush();let captured=C(db),local=C(db),merged,nextRevision;for(let attempt=0;attempt<3;attempt++){let read=await RPOnline.read();if(read.ownerId!==syncOwner||currentUser?.id!==syncOwner)throw Error('บัญชีเปลี่ยนระหว่างซิงค์ กรุณาโหลดหน้าใหม่');let remote=read.data||C(base);if(!knownBase&&read.data&&!hasLocalData(local)){merged=C(remote);}else if(!knownBase&&read.data){let blank={rooms:[],tenants:[],contracts:[],payments:[],owner:{},schemaVersion:3,rp3:{cycles:[],invoices:[],receipts:[],audit:[]}};if(remote.rooms.length&&!local.tenants.length&&!local.contracts.length&&!local.payments.length&&local.rooms.every(r=>/^warehouse-[1-4]$/.test(r.id)&&!r.rent))local.rooms=[];merged=RP.merge(blank,local,remote);}else merged=RP.merge(base,local,remote);delete merged._demo;try{nextRevision=await RPOnline.commit(read,merged,p=>{syncProgress=p.done<p.total?'กำลังส่งรูป '+p.done+' / '+p.total+' ชุด':'ส่งรูปครบแล้ว · กำลังบันทึกข้อมูล';renderStatus();});break;}catch(e){if(e.retryable&&attempt<2)continue;throw e;}}if(currentUser?.id!==syncOwner)throw Error('บัญชีเปลี่ยนระหว่างซิงค์ กรุณาโหลดหน้าใหม่');base=C(merged);onlineRevision=nextRevision;knownBase=true;if(RP.same(db,captured)){db=merged;rpStore.removeItem('rentpro_v3_pending');}else{db=RP.merge(captured,db,merged);rpStore.setItem('rentpro_v3_pending','1');}RentModel.syncPayments(db,today);rpStore.setItem('rentpro_v2',serializeLocal(db));persistAccount();await rpStore.flush();cloudReady=true;cloudError='';if(page!=='billing'&&!$('modal'))render();}catch(e){cloudError=authMessage(e);if(currentUser?.id===syncOwner)persistAccount();throw e;}finally{busy=false;syncProgress='';renderStatus();if(isDirty()&&!cloudError){clearTimeout(syncTimer);syncTimer=setTimeout(()=>sync().catch(()=>{}),1000);}}}
