let cacheTimer;document.addEventListener('input',e=>{let el=e.target;if(el.closest('#contract-form')&&['startDate','signedDate'].includes(el.name)){updateContractDates();}if(el.id==='search'){search=el.value;let pos=el.selectionStart;render();let s=$('search');s?.focus();if(s?.setSelectionRange)s.setSelectionRange(pos,pos);return;}if(!(page==='billing'||(['rent','utilities'].includes(page)&&categoryMode==='issue'))||el.closest('#modal'))return;let c=getWorking();if(c.state==='issued')return;if(el.dataset.invoiceTax){c.taxSelections=c.taxSelections||{};let tax=c.taxSelections[el.dataset.invoiceTax]||(c.taxSelections[el.dataset.invoiceTax]={});tax[el.dataset.taxKey]=el.value;try{let i=RentModel.build(db,c,uid,now()).invoices.find(i=>i.contractId===el.dataset.invoiceTax),row=el.closest('tr');if(row&&i?.taxPlan){let withheld=row.querySelector('[data-preview-withheld]'),net=row.querySelector('[data-preview-net]');if(withheld)withheld.textContent=M(i.taxPlan.withholding.amount);if(net)net.textContent=M(i.taxPlan.netDue);}}catch{}clearTimeout(cacheTimer);cacheTimer=setTimeout(cacheDraft,350);return;}if(el.dataset.segment){c.segments=c.segments||{};let v=c.segments[el.dataset.segment]||(c.segments[el.dataset.segment]={});if(el.value==='')delete v[el.dataset.part];else v[el.dataset.part]=el.value;}else if(el.dataset.read){let row=c.rows.find(r=>r.roomId===el.dataset.roomid);row[el.dataset.read]=el.value;let k=el.dataset.read.startsWith('water')?'water':'electric';let cell=$('use-'+k+'-'+row.roomId);if(cell)cell.textContent=row[k+'Now']!==''&&row[k+'Prev']!==''?Number((Number(row[k+'Now'])-Number(row[k+'Prev'])).toFixed(6)):'—';}else if(el.name){let parts=el.name.match(/^(water|electric)-(.+)$/);if(parts){c[parts[1]][parts[2]]=el.value;let total=$('total-'+parts[1]);if(total)total.textContent='฿'+M(billSum(c[parts[1]]));}else if(['due','note'].includes(el.name))c[el.name]=el.value;}clearTimeout(cacheTimer);cacheTimer=setTimeout(cacheDraft,350);});
