document.addEventListener('change',async e=>{let el=e.target;try{if(el.dataset.annexUpload){await uploadLeaseDocuments(el);return;}if(el.id==='lease-photo-files'){await uploadLeasePhotos(el);return;}if(el.closest('#deposit-form')&&el.name==='kind')updateDepositLimit();if(el.closest('#contract-form')&&el.name==='tenantId')refreshContractTenant();if(el.closest('#contract-form')&&['termYears','startDate','signedDate'].includes(el.name))updateContractDates();if(el.closest('#contract-form')&&['rentFreeEnabled','rentFreeFrom','rentFreeTo','startDate','termYears'].includes(el.name))updateFitOutFields();if(el.dataset.invoiceTax){let c=getWorking();if(c.state==='issued')throw Error('ใบแจ้งรอบนี้ออกแล้ว');c.taxSelections=c.taxSelections||{};let t=c.taxSelections[el.dataset.invoiceTax]||(c.taxSelections[el.dataset.invoiceTax]={});t[el.dataset.taxKey]=el.value;cacheDraft();render();return;}if(el.id==='period'){cacheDraft();period=el.value||today.slice(0,7);working=null;render();}if(el.id==='all-periods'){allPeriods=el.checked;render();}if(el.dataset.file&&el.files[0]){let file=el.files[0],kind=el.dataset.file;if(file.size>5*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('ใช้ภาพ PNG / JPEG / WebP ขนาดไม่เกิน 5 MB ต่อภาพ');let target=kind==='proof'?modalData:getWorking();if(kind!=='proof'&&target.state==='issued')throw Error('บิลรอบนี้ล็อกแล้ว');if(kind==='proof')modalData.loading=true;try{let imageData=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('อ่านไฟล์ไม่สำเร็จ'));r.readAsDataURL(file);}),assetId=crypto.subtle?Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer())),b=>b.toString(16).padStart(2,'0')).join(''):uid();let image={name:file.name,assetId,data:imageData};if(kind==='proof'&&target!==modalData)return;if(kind==='proof'){target.proof=image;target.loading=false;if($('proof-name'))$('proof-name').textContent='แนบแล้ว: '+file.name;}else{target[kind].attachment=image;rpStore.setItem(draftPrefix()+target.period,JSON.stringify(target));cacheDraft();if((page==='billing'||categoryMode==='issue')&&working===target)render();}}catch(error){if(kind==='proof')target.loading=false;throw error;}}if(el.id==='import'&&el.files[0]){let parsed=JSON.parse(await el.files[0].text()),data=parsed.data||parsed;if(!Array.isArray(data.rooms)||!Array.isArray(data.tenants)||!Array.isArray(data.contracts)||!Array.isArray(data.payments))throw Error('ไฟล์นี้ไม่ใช่ข้อมูล RentPro');if(Boolean(data._demo)!==demo)throw Error('ไฟล์สำรองต้องตรงกับโหมดข้อมูลจริง / ตัวอย่างที่กำลังเปิด');RP.migrate(data);let blank={rooms:[],tenants:[],contracts:[],payments:[],owner:{},schemaVersion:3,rp3:{cycles:[],invoices:[],receipts:[],audit:[]}},merged=RP.merge(blank,db,data);rpStore.setItem(demo?'rentpro_demo_before_import':'rentpro_backup_before_import',JSON.stringify({at:now(),data:db}));db=merged;save('นำเข้าข้อมูลจากไฟล์สำรอง');working=null;render();toast('นำเข้าข้อมูลแล้ว');}}catch(error){message(error);if(el.type==='file')el.value='';}});
