async function refreshCloud(){if(demo||!currentUser||authLoading||busy||working||$('modal')||document.visibilityState==='hidden')return;try{if(!cloudReady||isDirty()){await sync();return;}if(await RPOnline.changed(onlineRevision)){let result=await RPOnline.read();if(result.ownerId!==currentUser?.id)return;if(result.data){db=RP.merge(base,db,result.data);base=C(db);knownBase=true;onlineRevision=result.revision;rpStore.setItem('rentpro_v2',serializeLocal(db));persistAccount();cloudReady=true;cloudError='';render();}}}catch(e){cloudError=authMessage(e);renderStatus();}}
